WITH payload AS (SELECT $archive_payload$[{"id":"d4eacce7-8318-58dd-8544-1617c416a81e","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب والتلفظ -مطالبة املدعى باملجازاة -إقرار املدعى عليه بالدعوى -نكول املدعى عليه عن اليمن -إدانة املدعى عليه.","document_number":"34266049","case_number":"33659444","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/11","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب والتلفظ -مطالبة املدعى باملجازاة -إقرار املدعى عليه بالدعوى -نكول املدعى عليه عن اليمن -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/11 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34266049 :‬‬\n                         ‫َر ْق ُم الدعوى‪33659444 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34314958‬تاريخه‪1434/9/8 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب والتلفــظ ‪ -‬مطالبــة‬\n      ‫املدعــى باملجــازاة ‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬نكــول املدعــى عليــه‬\n                                             ‫عــن اليمــن ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                               ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه احلاضــر معــه قــام بضربــه بالعقــال‬\n      ‫بعــد مشــادة بينهمــا كمــا قــام بلعــن والديــه‪ ،‬ولــذا فقــد طلــب احلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بضــرب املدعــي‬\n      ‫وأنكــر لعنــه لوالديــه‪ -‬طلبــت احملكمــة مــن املدعــي البينــة علــى مــا‬\n      ‫جــاء يف دعــواه ممــا أنكــره املدعــى عليــه فقــرر أنــه ال بينــة لديــه وطلــب‬\n      ‫ميــن املدعــى عليــه علــى نفــي ذلــك فامتنــع عــن أدائهــا بحجــة نســيانه ملــا‬\n      ‫حــدث‪ -‬املدعــى عليــه أقــر بضــرب املدعــي وأنكــر لعنــه لوالديــه إال أنــه‬\n      ‫رفــض أداء اليمــن علــى نفــي ذلــك‪ -‬قضــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه مبــا نســب إليــه وقــررت ســجنه ملــدة عشــرين يوم ـ ًا وجلــده ثالثــن‬\n      ‫جلــدة دفعــة واحــدة‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه‪-‬‬\n\n‫‪273‬‬\n\f                    ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة األحســاء املكلــف برقــم ‪ 33659444‬وتاريــخ‬\n‫‪ 1433/11/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332041622‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/05/28‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب‬\n‫السجل املدني رقم ‪ .....‬وادعى ضد ‪ ......‬سعودي مبوجب السجل املدني‬\n‫ا يف دعــواه أن املدعــى عليــه حضــر لدينــا يف الشــركة‬         ‫رقــم ‪ ......‬قائ ـ ً‬\n‫لــدى مديــر خدمــة العمــاء وأثنــاء ذلــك قــال املدعــى عليــه لــي أنــت غيــر‬\n‫مــؤدب فقلــت لــه بلــى أنــا مــؤدب ثــم كررهــا مــرة أخــرى فقلــت لــه أنــا‬\n‫مــؤدب أكثــر منــك ومــن اللــي جابــك إلــى هنــا بعــد ذلــك قــام املدعــى‬\n‫عليــه بضربــي بالعقــال الــذي كان معــه خمــس أوســت ضربــات قبــل‬\n‫أن يفصــل بيننــا مديــر خدمــة العمــاء وبعدهــا أخــذ املدعــى عليــه يســب‬\n‫والــدي ووالدتــي بقولــه اهلل يلعــن أبــوك واهلل يلعــن أمــك اطلــب تأديــب‬\n‫املدعــى عليــه علــى مــا فعــل هــذه دعــواي وبعــرض ذلــك علــى املدعــى‬\n‫ا مــا ذكــره املدعــي يف دعــواه مــن أننــي قلــت لــه أنــت‬ ‫عليــه أجــاب قائـ ً‬\n‫غيــر مــؤدب فهــذا صحيــح وذلــك ألنــه رفــع الصــوت علــي بقولــه ســوف‬\n‫نأخــذ املبلــغ غصب ـ ًا عنــك وكذلــك مــا ذكــره املدعــي مــن أننــي قمــت‬\n‫بضربــه بالعقــال فهــذا صحيــح أيض ـ ًا وذلــك بعــد أن رفــع صوتــه علــي‬\n‫وتلفــظ علــي بــكالم ال أذكــر منــه إال أننــي قلــت لــه احفــظ صوتــك‬\n\n                                                                                         ‫‪274‬‬\n\f      ‫فأجابنــي بــأن صوتــه مبحــوح وهــذا صوتــه وأمــا مــا ذكــره املدعــي يف‬\n      ‫دعــواه مــن أننــي لعنــت والــده ووالدتــه فهــذا غيــر صحيــح هكــذا أجــاب‬\n      ‫وبســؤال املدعــي هــل لديــه بينــة علــى أن املدعــى عليــه قــام بلعــن والــده‬\n      ‫ا ليــس لــدي بينــة وأطلــب ميــن املدعــى عليــه علــى‬      ‫ووالدتــه أجــاب قائ ـ ً‬\n      ‫أنــه لــم يلعــن والــدي ووالدتــي هكــذا أجــاب وبعــرض ذلــك علــى املدعــى‬\n      ‫ا نســيت هــل قمــت بلعنــه أوال ألننــي كنــت يف ســاعة‬           ‫عليــه أجــاب قائ ـ ً‬\n      ‫غضــب واطلــب رفــع اجللســة حتــى يتأتــى لــي ســؤال الــذي كان حاضــر ًا‬\n      ‫وبنــاء عليــه فقــد مت رفــع اجللســة النتهــاء وقتهــا ويف يــوم الثالثــاء املوافــق‬\n      ‫‪1434/07/11‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف وفيهــا‬\n      ‫حضــر املدعــي واملدعــى عليــه وبســؤال املدعــى عليــه هــل قــام بلعــن والــد‬\n      ‫املدعــي ووالدتــه أو ال أجــاب قائــا كنــت يف حالــة غضــب وال أذكــر‬\n      ‫أي شــيء ممــا حــدث ولــم ألتــق حتــى أســأله هكــذا أجــاب فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بأنــه قــام بالتلفــظ‬\n      ‫علــى املدعــي وإقــراره بأنــه قــام بضربــة وحيــث إن املدعــى عليــه أنكــر‬\n      ‫أن يكــون لعــن والــد املدعــي ووالدتــه وحيــث إنــه ال بينــه للمدعــي علــى‬\n      ‫ذلــك وطلــب ميــن املدعــى عليــه وحيــث إن املدعى عليه رفــض أداء اليمني‬\n      ‫بحجــة نســيانه ملــا حــدث لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه‬\n      ‫مبــا يلــي أوال ‪ :‬ســجن املدعــى عليــه مــدة عشــرون يومــا يحتســب منها مدة‬\n      ‫توقيفــه بخصــوص هــذه القضيــة ثانيــا ‪ :‬جلــد املدعــى عليــه ثالثــون جلــده‬\n      ‫دفعــة واحــدة تعزيــرا هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك علــى‬\n      ‫املدعــي قــرر قناعتــه بــه وأمــا املدعــى عليــه فقــرر عــدم القناعــة وطلــب‬\n      ‫رفــع املعاملــة إلــى محكمــة االســتئناف بالئحــة فأجبتــه لطلبــه وأفهمتــه‬\n      ‫بــأن عليــه مراجعــة احملكمــة يــوم الســبت املوافــق ‪1434/07/15‬ه ـ‬\n\n\n‫‪275‬‬\n\f‫الســتالم نســخه مــن صــك احلكــم لالعتــراض عليــه خــال مــدة أقصاها‬\n‫ثالثــون يومــا مــن هــذا التاريــخ و أفهمتــه بأنــه إذا مضــت املــدة ولــم يقــدم‬\n‫الئحــة فــإن حــق االعتــراض يســقط ويكتســب احلكم القطعيــة وختمت‬\n‫اجللســة يف متــام الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/11‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد ففــي يوم‬\n‫االربعاء ‪1434/09/23‬هـ افتتحت اجللسة الساعة ‪ 01 : 15‬وفيها عادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب خطــاب‬\n‫فضيلــة رئيســها ذي الرقــم ‪ 342093394‬والتاريــخ ‪1434/09/20‬ه ـ‬\n‫مرفق ـ ًا بهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثالثيــة‬\n‫نصــه‬‫الثانيــة رقــم ‪ 34314958‬وتاريــخ ‪1434/09/08‬ه ـ املتضمــن مــا ُّ‬\n‫‪ :‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫لوحــظ ان صــورة الضبــط املرفقــة ناقصــة والبــد مــن إرفــاق صــورة‬\n‫ضبــط مكتملــة ومــن ثــم اعــادة املعاملــة واهلل املوفــق ‪ .‬قاضــي اســتئناف‬\n‫د‪ .‬ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف د‪ .‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫ختمــه وتوقيعــه أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة قضــاة محكمــة‬\n‫االســتئناف وفقهــم اهلل بــكل خيــر بأنــه مت إجــراء الــازم وبــه ختمــت‬\n‫اجللســة الســاعة (‪ )1:20‬وبــاهلل التوفيــق وصلــى اهلل وس ـلّم علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/09/23‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/2314894‬ج‪ 2‬وتاريــخ ‪1434/10/14‬ه‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n      ‫املكلــف برقــم ‪ 34/2093394‬وتاريــخ ‪1434/10/7‬ه املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....(/‬املســجل‬\n      ‫برقــم ‪ 34266049‬وتاريــخ ‪1434/7/11‬ه اخلــاص بدعــوى‪ ).....( /‬ضــد‪/‬‬\n      ‫(‪ ).....‬يف قضيــة اعتــداء بالضــرب وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى‬\n      ‫قرارنــا رقــم ‪/34314958‬ج‪/2‬ب وتاريــخ ‪1434/9/8‬ه قررنــا املصادقــة‬\n      ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف ‪1434/11/18‬هــ‪.‬‬\n\n\n\n\n‫‪277‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":273,"source_page_end":277,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f4021d994856c1cca8b7adf2fbb7964c00e3a619d1efcd304301ba191fc3c9cc","normalized_text_hash":"1d76c0b70a2c098ec1721c24e86bf0afa6cab1fea0876670c11621d764c02864","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p273-34266049"},{"id":"05b2a41f-f424-56fd-aea3-60f9be675fcf","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -تشهير وتشويه سمعة -مطالبة املدعي بالتعزير -تعذر الصلح بن الطرفن -شهادة الشهود العدول شرع ا- إدانة املدعى عليه واحلكم عليه بالسجن واجللد وأخذ التعهد .","document_number":"34187322","case_number":"33677165","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإليضاح األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/14","year":"1434","subject":"إيذاء الغير (حق خاص) -تشهير وتشويه سمعة -مطالبة املدعي بالتعزير -تعذر الصلح بن الطرفن -شهادة الشهود العدول شرع ا- إدانة املدعى عليه واحلكم عليه بالسجن واجللد وأخذ التعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/14 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34187322 :‬‬\n                   ‫َر ْق ُم الدعوى‪33677165 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34243398‬تاريخه‪1434/6/18 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬تشــهير وتشــويه ســمعة ‪ -‬مطالبــة املدعــي‬\n‫بالتعزيــر‪ -‬تعــذر الصلــح بــن الطرفــن‪ -‬شــهادة الشــهود العدول شــرع ًا‪-‬‬\n     ‫إدانــة املدعــى عليــه واحلكــم عليــه بالســجن واجللــد وأخــذ التعهــد ‪.‬‬\n\n\n\n\n‫املادتــان (‪ )1/176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                       ‫التنفيذ يــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه أثنــاء عملهمــا يف مدرســة واحــدة قــام‬\n‫بتشــويه ســمعته وذلــك باحلديــث عنــه بــن املدرســن علــى أنــه صاحــب‬\n‫فكــر ضــال وال والء لــه للوطــن‪ ،‬ولــذا فقــد طلــب احلكــم علــى املدعــى‬\n‫عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n‫دعــوى املدعــي‪ -‬طلبــت احملكمــة مــن املدعــي تقــدمي بينتــه فأحضــر‬\n‫شــهودا شــهدوا مبــا يثبــت دعــواه‪ -‬املدعــى عليــه ســعى لإلضــرار باملدعــي‬\n‫والوشــاية بــه والتدخــل فيمــا ال يعنيــه رغبــة يف االنتقــام‪ -‬جــرى نصــح‬\n‫املتداعيــن بالصلــح إال أنهمــا رفضــا الصلــح‪ -‬قضــت احملكمــة بســجن‬\n‫املدعــى عليــه خمســة عشــر يوم ـ ًا وبجلــده خمســن جلــده تكــرر عليــه‬\n‫ثــاث مــرات مــع أخــذ التعهــد علــى طــريف الدعــوى بااللتــزام بــاآلداب‬\n\n                                                                                   ‫‪278‬‬\n\f      ‫اإلســامية احلميــدة وكــف أذى كل منهمــا عــن اآلخــر‪ -‬قنــع املدعــي‬\n      ‫باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف‬\n                                 ‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33677165‬وتاريــخ ‪1433/11/27‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332120472‬وتاريــخ ‪ 1433/11/27‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة الســاعة ‪10 :30‬‬\n      ‫وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ......‬قائــا يف دعــواه إن هــذا احلاضــر معي كان زميال لي باملدرســة‬\n      ‫التــي كنــت اعمــل بهــا وهــي مدرســة ثانويــة ‪ ....‬رحمــه اهلل ويف أحــد‬\n      ‫األيــام نشــر فكــرة عنــي بــن املدرســن علــى أننــي صاحــب فكــر ضــال‬\n      ‫وال والء لــي للوطــن وأنــي اكــذب ونظــرا ألن املدعــى عليــه شــوه ســمعتي‬\n      ‫وأنــا احمــل خــاف مــا يذكــره واطلــب مجازاتــه وعقوبتــه حلقــي اخلــاص‬\n      ‫علــى رميــه لــي هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫بقولــه مــا يذكــره املدعــي غيــر صحيــح والصحيــح هــو انــه كان معلــم‬\n      ‫بهــذه الثانويــة التــي يذكرهــا وأنــا كنــت وكيــا باملدرســة لكــن لــم‬\n      ‫اقــل شــيئ ًا مــن هــذا القــول ابــد ًا وبعــرض ذلــك علــى املدعــي أجــاب بقولــه‬\n      ‫مــا ذكرتــه هــو الصحيــح ولــدي البينــة التــي تثبــت صحــة كالمــي‬\n      ‫ودعــواي وبطلــب البينــة منــه اســتعد بإحضارهــا عليــه وألهميــة البينــة‬\n\n‫‪279‬‬\n\f‫فقــد أمــرت برفــع اجللســة إلــى يــوم آخــر ويف يــوم آخــر حضــر املدعــي‬\n‫باحلــق اخلــاص ولــم يحضــر املدعــي عليــه وبطلــب البينــة منــه احضــر ‪/‬‬\n‫ســعودي اجلنســية مبوجــب بطاقــة أحــوال رقــم ( )ســعودي اجلنســية‬\n‫مبوجــب بطاقــة أحــوال () وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد‬\n‫كل واحــد مبفــرده بقولــه اشــهد هلل تعالــى بــأن املعلــم ‪ /‬كان وكيــل‬\n‫مدرســة ابــن ابــي حــامت وبعــد اليــوم الوطنــي لعــام ‪1433‬ه ـ انتشــر يف‬\n‫املدرســة بــأن املعلــم‪ /‬رجــل ينتمــي الفكــر الضــال وليــس عنــده وطنيــة‬\n‫وتأكدنــا مــن اإلشــاعة مــن هــذا األمــر بوجــود محققــن مــن مكتــب‬\n‫التربيــة و التعليــم بالعزيزيــة ملدرســتنا التــي نعمــل بهــا لتحقيــق مــع املعلــم‬\n‫بهــذا اخلصــوص حتــى صــار بعــض املعلمــن يعلقــون علــى املعلــم ‪ /‬بضعف‬\n‫الوطنيــة وســمعنا احدهــم يقــول لــو اســميت ابنتــك والء حتــى يثبــت‬\n‫والئــك وكتــب علــى صحيفــة انــا أحــب وطنــي وكتبهــا أحــد املعلمــن‬\n‫ولــم يكتبهــا وإمنــا كتبهــا أحــد املعلمــن وكثــر الــكالم حــول هــذا‬\n‫املوضــوع وبســؤال املدعــي باحلــق اخلــاص عــن مزيــد بينــة اجــاب بقولــه‬\n‫نعــم لــدي اطلــب رفــع اجللســة الــى يــوم آخــر وألهميــة البينــة وتغيــب‬\n‫املدعــى عليــه فقــد امــرت برفــع اجللســة الــى يــوم آخــر ويف يــوم آخــر‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي باحلــق اخلــاص ‪ /‬املدعــى عليــه ‪/‬‬\n‫وبســؤال املدعــى عليــه عــن الشــهادة أجــاب املدعــى عليــه بقولــه هــذه‬\n‫الشــهادة غيــر صحيحــة فلــم أقــل شــيء ابــد ًا ولــم اكــن ســبب ًا يف نشــرها‬\n‫وامــا حالهمــا فــا اطعــن بدينهــم اال انهــم زمــاء عمــل ولعلهــم وجــدوا‬\n‫اثــرة يف اثنــاء عملهــم حــال كونــي وكيــل للمدرســة الــذي نعمــل بهــا ثــم‬\n‫جــرى ســؤال املدعــي باحلــق اخلــاص عــن مزيــد بينــة قــدم خطابـ ًا منســوب ًا‬\n‫الــى املدعــى عليــه وموجــه إلــى ســعادة مديــر مكتــب التربيــة والتعليــم‬\n\n\n                                                                                          ‫‪280‬‬\n\f      ‫بالعزيزيــة ونصــه‪« :‬الســام عليكــم ورحمــة اهلل وبركاتــه وبعــد ال‬\n      ‫يخفــى عليكــم مــا تعيشــه بالدنــا مــن أفــراح مبناســبة اليــوم الوطنــي‬\n      ‫الثانــي والثمانــون للمملكــة إال أن هنــاك مــن يعانــون مــن قصــور يف‬\n      ‫أفهامهــم ممــا ينعكــس ســلبا علــى وحــدة بالدنــا يف ظــل مــا يتصورونــه‬\n      ‫مــن فكــر ال أدري مــن أيــن جــاءوا بــه ممــا ســبق أشــكو لســعادتكم مــا‬\n      ‫قــام بــه املعلــم ‪ ....‬معلــم التربيــة اإلســامية وذلــك عنــد احتفــاء املدرســة‬\n      ‫باليــوم الوطنــي وعنــد حضــور املرشــدين الطالبيــن لغرفــة املديــر‬\n      ‫لتصويــر مديــر املدرســة مــع مجموعــة مــن الطــاب وصــف ذلــك بأنــه‬\n      ‫نفــاق وريــاء علــى مســمع مــن طالبنــا وأطلــق ضحــكات غيــر الئقــة‬\n      ‫باملوقــف آمــل ومــن منطلــق احملافظــة علــى وحــدة البــاد والقضــاء علــى‬\n      ‫هــذه الظواهــر املنافيــة ملــا يصــدر مــن والة األمــر مــن توجيهــات مســاءلة‬\n      ‫املعلــم املذكــور و الرفــع عنــه للجهــات املختصــة واهلل يحفظكم مقدمه‬\n      ‫وكيــل ثانويــة ‪1433/11/13‬هــ»‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أجــاب بقولــه نعــم هــذا اخلطــاب كتبتــه ورفعتــه لســعادة مديــر التربيــة‬\n      ‫والتعليــم بنــاء علــى توجيــه مــن مديــر املدرســة التــي كنــت أعمــل بهــا‬\n      ‫ويدعــي األســتاذ وفيــه طالبـ ًا التحقــق والتحقيــق مــع املدعــي ملــا بــدر منــه‬\n      ‫ا جــاءت جلنــة مــن مكتــب التربيــة والتعليــم إلكمــال الزمهــا‬             ‫وفع ـ ً‬\n      ‫وبعدهــا لــم أكتــب شــيء نحــوه ال مــن بعيــد وال مــن قريــب وبعــرض ذلــك‬\n      ‫علــى املدعــي يف احلــق اخلــاص أجــاب بقولــه بلــى كتــب غيرهــا ولــم‬\n      ‫يكتفــي إذ أنــه وبعــد التحقيــق معــي وبعــد مضــي أربعــة أيــام قمــت بعمــل‬\n      ‫يضاهــي مــا نســبه لــي مــن أنــي أحمــل فكــر ًا ضــا ًال وأنــه ال يوجــد لــدي‬\n      ‫وطنيــة فبتاريــخ ‪1433/11/19‬ه ـ لبســت وشــاح ًا كتبــت عليــه الوطــن‬\n      ‫يف قلوبنــا ومعــي علــم هــذه البــاد وكل مــا دخلــت حصــة تخصنــي‬\n\n\n‫‪281‬‬\n\f‫تكلمــت بدايــة احلصــة عــن الوطنيــة وعــن وجــوب طاعــة والة األمــر‬\n‫وتفاجــأت بكتابــة محضــر مــن هــذا احلاضــر ذكــر فيــه مــا فعلتــه ويزيد‬\n‫وصفـ ًا لــي بــأن مــا أفعلــه يؤكــد صراحــة اســتهزائي لليــوم الوطنــي وأنــي‬\n‫أصــف االحتفــاء باملناســبة بأنــه نفــاق وريــاء وبعــرض ذلــك علــى املدعــى‬\n‫عليــه أجــاب بقولــه نعــم كتــب هــذا احملضــر وشــاركت فيــه أنــا ومديــر‬\n‫املدرســة اذ أن مــا فعلــه هــذا ُيعــد خطــأ وهــذا احملضــر بأمــر مــن املديــر‬\n‫وهــذا اثبــات واقعــة ليــس إال وقــدم صــورة مــن احملضــر ونصــه‪ « :‬إنــه يف‬\n‫يــوم االربعــاء ‪1433/11/24‬ه ـ حضــر املعلــم ‪ ...... /‬البسـ ًا وشــاح ًا علــى‬\n‫كتفــه وصــدره وهــو يضحــك ودخــل االدارة وجتــول يف املدرســة‬\n‫والســاحات بحــركات ال تنــم إال عــن اســتهتار باالحتفــاء باملناســبة‬\n‫الوطنيــة وهــي االحتفــاء باليــوم الوطنــي ‪ 82‬للمملكــة وهــو مــا يؤكــد‬\n‫صراحــة اســتهتاره الســابق ووصفــه االحتفــاء باملناســبة يف غيــر وقتهــا‬\n‫حتــى يذهــب الهــدف االساســي لالحتفــاء وهــذا محضــر بذلــك‪ -1‬مديــر‬\n‫املدرســة ‪ -2‬وكيــل املدرســة توقيــع ‪ -3‬مرشــد طالبــي‪ .‬نعــم يف أرجــاء‬\n‫املدرســة توقيــع‪-4 .‬نعــم شــاهدته باملالبــس الوطنيــة والعلــم والنشــيد‬\n‫الوطنــي توقيــع‪ .‬مديــر املدرســة وختــم املدرســة»‪ .‬بســؤال املدعــي باحلــق‬\n‫اخلــاص عــن مزيــد بينــة يقدمهــا أجــاب بقولــه نعــم لــدي اطلب رفع اجللســة‬\n‫الــى يــوم آخــر واحلــال مــا ذكــر وألهميــة البينــة فقــد أمــرت برفــع اجللســة‬\n‫الــى يــوم آخــر ويف يــوم آخــر افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه‬\n‫وبســؤال املدعيــان عــن رغبتهمــا يف اضافــة أجــاب املدعــى عليــه بقولــه‬\n‫نعــم واحضــر الشــاهد ســعودي اجلنســية مبوجــب بطاقــة أحــوال رقــم‬\n‫وبســؤاله عمــا لديــه مــن شــهادة شــهد بقولــه اشــهد هلل تعالــى بينمــا‬\n‫كنــت يف غرفــة املديــر وبعــد االنتهــاء مــن اليــوم الوطنــي قامــت املدرســة‬\n\n\n                                                                                        ‫‪282‬‬\n\f      ‫بوضــع احتفــال بهــذه املناســبة وكنــت أقــوم بتصويــر املديــر ومعــه بعــض‬\n      ‫الطــاب ودخــل املدعــى عليــه يف اإلدارة ورأى املنظــر وســأل عــن هــذه‬\n      ‫املناســبة أجــاب املديــر بــأن هــذه للــذي عنــده والء للوطــن فقــال هــذا‬\n      ‫كلــه ريــاء وبعدهــا انتهــى املوقــف وتفرقنــا هــذا مــا لــدي مــن شــهادة‬\n      ‫وبعــرض هــذه الشــهادة علــى املدعــي أجــاب بقولــه هــذا صحيــح ألننــي‬\n      ‫أكــرر مــا ذكــره املديــر قبــل يــوم حينمــا طلــب منــي القيــام بأعمــال‬\n      ‫اليــوم الوطنــي وقــال انهــا مجــرد ريــاء وأنــا أجبــت علــى املديــر بنفــس‬\n      ‫العبــارة التــي قالهــا باألمــس ورددتهــا عليــه وأنــا ال أنكــر الشــهادة و‬\n      ‫الشــاهد هــو عــدل ثقــة ثــم جــرى ســؤال املدعــى عليــه عــن مزيــد بينــة‬\n      ‫أجــاب بقولــه ال مزيــد بينــة لــدي ثــم ذكــر املدعــي باحلــق اخلــاص ان هــذا‬\n      ‫الشــاهد يشــهد لــه وأنــه حضــر للشــهادة لــه وعليــه وبســؤال الشــاهد‬\n      ‫اثباتــه تفصيــا أجــاب بقولــه نعــم وأنــا اشــهد انــه ملــا ســمع املدعــى عليــه‬\n      ‫بهــذا الــكالم قــام واعــد محضــرا بذاتــه وكتــب خطابـ ًا موجهــا ملديــر‬\n      ‫مركــز التربيــة بذلــك وحاولــت منعــه أن يتخلــى عــن اخلطــاب فأبــى‬\n      ‫وأصــر علــى ان يكتــب هــذا اخلطــاب وحاولــت معــه أن يكــون هــذا‬\n      ‫األمــر داخليــا مــع محاولــة عالجــه فلــم يســتجيب وذهبــت للمديــر وطلبــت‬\n      ‫منــه أن يقنــع الوكيــل املدعــى عليــه عــن اخلطــاب فأجــاب بقولــه أنــا‬\n      ‫حاولــت مــع الوكيــل وكلمتــه عــدة مــرات اال أنــه أصــر علــى كتابتــه‬\n      ‫ورفعــه وطلــب منــي أن اكلمــه وأقنعــه فأصــر فذهبــت للوكيــل (املدعى‬\n      ‫عليــه) وطلبــت منــه وأصــر علــى كتابتــه هــذا مــا لــدي وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه أجــاب بقولــه نعــم هــذا صحيــح وهــو مــا حصــل وأنــا‬\n      ‫بينــت للشــاهد ‪ ....‬حــال اقناعــه لــي بعــدم رفــع خطابــي بأنــه ســبق وأنــه‬\n      ‫شــارك املدعــي يف موضــوع تبنــاه معلــم آخــر يدعــى وشــهدوا علــي بأمــور‬\n\n\n‫‪283‬‬\n\f‫ليســت فينــي وحاولــت أن اثنيهــم وكلمهــم غيــري ولــم ميتثلــوا وكانــوا‬\n‫يريــدون نقلــي مــن هــذه املدرســة ويثنوننــي مــن عملــي وامــا الشــاهد فهــو‬\n‫ثقــة هــذا مــا لــدي ثــم جــرى ســؤال املدعــى عليــه مــن وجــود تناقــض يف‬\n‫إجابتــه مــن أن املديــر وجهــه بكتابــة اخلطــاب الــذي فيــه دعــوى ضــد‬\n‫املدعــى عليــه أجــاب بقولــه ال تناقــض فمــا قلتــه هــو صحيــح واملديــر لــن‬\n‫يحضــر للشــهادة وال بينــة لــدي علــى دعــواي هكــذا أجــاب وبســؤال‬\n‫الطرفــن عــن رغبتهمــا يف إضافــة فأجــاب املدعــى عليــه بقولــه نعــم لــدي‬\n‫ارغــب يف رفــع اجللســة إلــى يــوم آخــر عليــه ولطلــب املدعــى عليــه برفــع‬\n‫اجللســة إلــى يــوم آخــر كــي يحضــر اجللســة لــذا وملــا ســبق كلــه فقــد‬\n‫أمــرت برفــع اجللســة إلــى يــوم آخــر ويف يــوم آخــر افتتحــت اجللســة وفيهــا‬\n‫حضــر املتداعيــان وفيهــا احضــر املدعــى مزكيــان للشــاهدين و وهمــا‬\n‫ســعودي اجلنســية مبوجــب بطاقــة أحــوال رقــم (‪ )......‬وســعودي اجلنســية‬\n‫مبوجــب بطاقــة أحــوال رقــم (‪ )......‬وبســؤالهما عمــا لديهمــا مــن شــهادة‬\n‫شــهد كل واحــد بقولــه اشــهد هلل تعالــى بــأن كل مــن الشــاهد همــا‬\n‫عــدالن ثقتــان ومــن أهــل الصــاح وهمــا مرضيــا الشــهادة وبســؤال‬\n‫املتداعيــان عــن رغبتهمــا يف إضافــة أجــاب املدعــي بقولــه نعــم إن هــذا‬\n‫الرجــل املدعــى عليــه بفعلــه هــذا التدخــل مبــا ال يعنيــه والتشــهير بــي‬\n‫وإرادة التشــفي بالكــذب علــي والتعامــل ضــدي إلحلــاق االذى واألضــرار‬\n‫بــي ولفــت أنظــار وزارة الداخليــة واجلهــات املعنيــة مــن دون وجــه حــق لهــو‬\n‫انتقــام منــه إذا أنــه فعــل مــا فعــل وكتــب مــا كتــب للجهــات املعنيــة‬\n‫وطلبــه الكتابــة للجهــات املســئولة إلحلــاق االذى بــي بالتحقيــق مــع ردة‬\n‫فعــل ملــا شــهدت ضــده ابتــداء قبــل هــذا كلــه يف قضيــة يف التعليــم‬\n‫فجعلــت العــداوة يف صــدره تــؤزه أز ًا حتــى يفتــك بــي وينهــي بســجني‬\n\n\n                                                                                     ‫‪284‬‬\n\f      ‫وخالفــه ولــم يعمــد إلــى النصيحــة الشــرعية إذ هــو الواجــب عليــه كونــه‬\n      ‫مربــي ومعلــم وهــذا مــا يقربــه وانــا اطالــب اصــدار عقوبــة لــه رادعــة‬\n      ‫وزاجــره توقفــه عــن االفتيــات علــى النــاس ورميهــم وعــدم التدخــل يف‬\n      ‫شــئونهم وعــدم تخطــى الســلم املرســوم لــكل شــخص هــذا مــا أريــد‬\n      ‫اضافتــه واطالــب بــه وبعــرض ذلــك علــى املدعــى عليــه اجــاب بقولــه نعــم‬\n      ‫مــا يذكــره مــن ان املدعــى قــد شــهد علــي يف التعليــم ظلم ـ ًا وعدوان ـ ًا‬\n      ‫فــأردت ان اخــذ حقــي باحلــق بتســجيل كل مــا يصــدر منــه مــن خطــأ وانــا‬\n      ‫مريــض حاليـ ًا وال نفــس لــي بطــول املجادلــة معــه وال اقــول اال حســبنا اهلل‬\n      ‫ونعــم الوكيــل ثــم جــرى ســؤال املدعــى عليــه مــن وجــود جلــان حتقــق مــع‬\n      ‫املدعــى اجــاب بقولــه نعــم جــاءت جلنــة علــى قــرار كتابتــي ثــم جــاءت جلنــة‬\n      ‫أخــرى ثانيــة علــى قــرار كتابتــي األخــرى وانــا تنازلــت عــن دعــواي ضــده‬\n      ‫هكــذا اجــاب وبســؤالهما جميعـ ًا املدعــى واملدعــى عليــه عــن رغبتهمــا‬\n      ‫يف اضافــة قبــل اقفــال بــاب املرافعــة اجــاب كل واحــد منهمــا ال مزيــد‬\n      ‫ـاء علــى الدعــوى واإلجابــة وحيث‬    ‫لدينــا ونكتفــي مبــا ذكرنــاه عليــه فبنـ ً‬\n      ‫ا للجهــة املســئولة مــع‬ ‫صــادق املدعــى عليــه بالكتابــة حــال كونــه وكيـ ً‬\n      ‫وجــود درجــة أعلــى منــه ورمــي املدعــى ‪ /‬بقصــور الفهــم وان هــذا‬\n      ‫ينعكــس ســلبي ًا علــى وحــده البــاد وطلــب الرفــع عنــه للجهــات املختصــة‬\n      ‫وقــد افــاد انــه هــذا بتوجيــه مــن مديــر املدرســة وظهــر عــدم صحــة ذلــك‬\n      ‫بالبينــة وحيــث ظهــر مــن البينــة املعدلــة شــرع ًا تشــويه ســمعة املدعــي‬\n      ‫وحضــور جلــان حتقيــق كلــه جــراء مــا كتبــه املدعــى عليــه وتدخلــه فيمــا‬\n      ‫ال يعنيــه مــع عــدم اتخــاذ الســبيل األمثــل وتخطيــه اجلهــة الرســمية مــن‬\n      ‫مديــر اإلدارة مــع طلبــه الكــف عــن الكتابــة وقــد ظهــر التشــفي‬\n      ‫باالنتقــام مــن املدعــى حــال شــهادته عليــه ملــا تقــدم عليــه مــن شــكوى‬\n\n\n‫‪285‬‬\n\f‫وحيــث جــرى نصــح املتداعيــان بطــي صفحــات املاضــي صلح ـ ًا لوجــه‬\n‫اهلل تعالــى وبــدء صفحــة جديــده مليئــة باإلخــاء واحلــب والتســامح وحيــث‬\n‫ظهــر مــن الطرفــن إصرارهمــا ثــم أظهــر مؤخــر ًا عــدم تنازلــه عــن‬\n‫الدعــوى لوجــود أضــرار كثيــره مــن جلــان التحقيــق حتقــق معــه بســبب‬\n‫هــذه الدعــوى الكاذبــة عليــه وملــا ســبق كلــه فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه ‪ /‬بالســعي إلضــرار املدعــى عليــه والوشــاية بــه والتدخــل‬\n‫فيمــا ال يعنيــه رغبــة يف االنتقــام وعــدم اتخــاذ الســبل الصحيحــة التــي‬\n‫أمرتنــا بهــا الشــريعة املطهــرة عليــه ونظــر ًا الســتحقاق املدعــى عليــه‬\n‫للعقوبــة فقــد حكمــت علــى املدعــى عليــه للحــق اخلــاص تعزيــر ًا بســجنه‬\n‫خمســة عشــر يومـ ًا وبجلــده خمســن جلــده تكــرر عليــه ثــاث مــرات مــع‬\n‫أخــذ التعهــد عليهمــا جميع ـ ًا بااللتــزام بــاآلداب اإلســامية احلميــدة‬\n‫وكــف األذى لــكل منهمــا عــن اآلخــر وبعــرض احلكــم علــى الطرفــن‬\n‫قــرر املدعــي القناعــة باحلكــم كمــا قــرر املدعــى عليــه عــدم القناعــة‬\n‫وذلــك بعــد ان افهــم الطرفــان بحقهمــا باالعتــراض وطلــب اســتئناف‬\n‫احلكــم ورغــب املدعــى عليــه اســتالم نســخة مــن احلكــم لالعتــراض‬\n‫عليــه وافهــم بــأن لــه احلضــور للمكتــب يف يــوم االثنــن بتاريــخ‬\n‫‪1434/4/15‬ه ـ يف متــام الســاعة ‪ 10.15‬لالســتالم نســخة مــن احلكــم‬\n‫لالعتــراض وان لــه مهلــة ثالثــن يومــا مــن تاريــخ اســتالمه لتقــدمي‬\n‫اعتراضــه وانــه اذا انقضــت املــدة ولــم يتقــدم باعتراضــه ســقط حقــه يف‬\n‫االعتــراض وذلــك حســب املــواد رقــم (‪ )1/176‬و(‪)178‬مــن نظــام‬\n‫املرافعــات الشــرعية ولوائحــه التنفيذيــة ففهــم ذلــك واقفلــت اجللســة يف‬\n‫متــام الســاعة ‪ 11.15‬مــن هــذا اليــوم الثالثــاء املوافــق ‪1434/4/8‬ه ـ‬\n   ‫وباهلل التوفيق وصلى اهلل وسلم على نبينا محمد وآله وصحبه وسلم‪.‬‬\n\n\n                                                                                 ‫‪286‬‬\n\f      ‫احلمــد هلل وحــدة والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1434/8/15‬ه ـ ويف متــام الســاعة ‪10:15‬‬\n      ‫افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫رقــم‪ 341234900‬وتاريــخ ‪1434/6/26‬ه ـ املرفــق بهــا القــرار رقــم‬\n      ‫‪ 34243398‬وتاريــخ ‪1434/6/18‬ه ـ املتضمــن أنــه لوحــظ مــا يلــي‪ :‬أن‬\n      ‫مــا حكــم بــه فضيلتــه مــن ســجن وجلــد كثيــر ولعــل فضيلتــه يكتفــي‬\n      ‫ا واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬ ‫باجللــد وتخفيفــه قلي ـ ً‬\n      ‫وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ....‬ختــم وتوقيــع قاضــي اســتئناف ‪....‬‬\n      ‫ختــم وتوقيــع رئيــس الدائــرة د‪ ....‬ختــم وتوقيــع عليــه وبعــد االطــاع علــى‬\n      ‫مــا الحظــه أصحــاب الفضيلــة وفقهــم اهلل لــم يظهــر لــي تخفيــف مــا‬\n      ‫حكمــت بــه تعزيــر ًا للحــق اخلــاص ورأيــت مناســبة العقوبــة التعزيريــة‬\n      ‫ملــا بــدر منــه جــزاء لــه وردع ـ ًا ألمثالــه ملــا ذكــر مــن حيثيــات وهــذا مــا‬\n      ‫توصلــت لــه بعــد عــدة جلســات وإصــرار مــن الطرفــن وأخــذ وعطــاء‬\n      ‫وتأمــل هــذا مــا ظهــر لــي واهلل املوفــق وأمــرت برفــع كامــل املعاملــة‬\n      ‫حملكمــة االســتئناف إلكمــال الزمهــا وأقفلــت اجللســة يف متــام الســاعة‬\n      ‫‪ 10:30‬مــن هــذا اليــوم االثنــن املوافــق ‪1434/8/15‬ه ـ وبــاهلل التوفيــق‬\n           ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪287‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":278,"source_page_end":287,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"55f52ca46a1f006b2feac6655b5efab6bb50a90c5eee40242412d423ce05c1ff","normalized_text_hash":"c451a3fb53e4a95a427fd0ce50949a4bea752bf3718ceb1d6d627b7fe880714e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p278-34187322"},{"id":"56239511-9bdb-5e09-b6bb-dc49674077ec","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -شكوى كيدية -مطالبة املدعي بالتعزير- مين املدعى عليه على نفي الدعوى -عدم ثبوت كيدية الدعوى- العجز عن إثبات الدعوى ال يكفي لثبوت كيديتها -رد الدعوى .","document_number":"332141993","case_number":"33681725","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/26","year":"1434","subject":"إيذاء الغير (حق خاص) -شكوى كيدية -مطالبة املدعي بالتعزير- مين املدعى عليه على نفي الدعوى -عدم ثبوت كيدية الدعوى- العجز عن إثبات الدعوى ال يكفي لثبوت كيديتها -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/26 :‬هـ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪332141993 :‬‬\n                     ‫َر ْق ُم الدعوى‪33681725 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34384074‬تاريخه‪1434/12/22 :‬هـ‬\n\n\n  ‫إيــذاء الغيــر (حــق خــاص)‪ -‬شــكوى كيدية‪ -‬مطالبــة املدعي بالتعزير‪-‬‬\n  ‫ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬عــدم ثبــوت كيديــة الدعــوى‪-‬‬\n    ‫العجــز عــن إثبــات الدعــوى ال يكفــي لثبــوت كيديتهــا‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬األصل براءة الذمة‪.‬‬\n                                     ‫‪ -2‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n\n\n\n\n  ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــدم ضــد موكلــه شــكوى‬\n  ‫كيديــة ملركــز الشــرطة اتهمــه فيهــا بأنــه هــدده بالقتــل فتــم إحالــة‬\n  ‫موكلــه للتحقيــق علــى إثرهــا إال أنــه لــم يتــم إدانتــه مبــا نســب إليــه‪،‬‬\n  ‫ولــذا فقــد طلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى‬\n  ‫عليــه بأنــه قــدم شــكوى ضــد املدعــي ودفــع بأنهــا ليســت كيديــة‬\n  ‫لكــون املدعــي هــدده حقيقــة باأللفــاظ املذكــورة يف جوابــه واســتعد‬\n  ‫بإقامــة البينــة علــى هــذا الدفــع‪ -‬أحضــر املدعــى عليــه شــاهدين‬\n  ‫فشــهدا بصحــة تهديــد املدعــي للمدعــى عليــه إال أن احملكمــة لــم‬\n  ‫تقبــل شــهادتهما لكونهمــا محــل تهمــة‪ -‬العجــز عــن إثبــات الشــكوى‬\n  ‫ال يكفــي لثبــوت كيديتهــا وشــهادة الشــهود مــع كونهــا ليســت بينــة‬\n\n                                                                                      ‫‪288‬‬\n\f      ‫كاملــة إال أنهــا تقــوي جانــب املدعــى عليــه‪ -‬قــررت احملكمــة توجيــه‬\n      ‫اليمــن املكملــة للمدعــى عليــه علــى إثبــات مــا دفــع بــه فأداهــا طبــق‬\n      ‫مــا طلــب منــه‪ -‬قضــت احملكمــة بعــدم اســتحقاق املدعــي ملــا يطالــب‬\n      ‫بــه مــن عقوبــة املدعــى عليــه لعــدم ثبــوت موجبهــا‪ -‬عــارض املدعــي علــى‬\n            ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 33681725‬وتاريــخ ‪1433/11/29‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332141993‬وتاريــخ ‪1433/11/29‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 15‬‬\n      ‫ا شــرعي ًا ســوري‬  ‫وفيهــا حضــر ‪ .....‬ســعودي بالســجل رقــم ‪ ....‬وكي ـ ً‬\n      ‫اجلنســية بالوكالــة الصــادرة مــن كتابــة عــدل اخلبــر برقــم ‪3366888‬‬\n      ‫وتاريــخ ‪1433/5/9‬ه ـ وفيهــا حــق املطالبــة واملخاصمــة واملرافعــة‬\n      ‫واملدافعــة وســماع الدعــوى والــرد عليهــا واإلنــكار واإلقــرار وطلــب‬\n      ‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n      ‫واإلجابــة واجلــرح والتعديــل وحضــر حلضــوره ســعودي بالســجل رقــم‬\n      ‫وادعــى املدعــي وكالــة قائــا يف دعــواه ســبق وأن تقــدم املدعــى عليــه‬\n      ‫بشــكوى كيديــة لــدى شــرطة اخلبــر يتهــم فيهــا موكلــي بأنــه قــام‬\n      ‫بتهديــده بالقتــل وقــد نتــج عــن التحقيــق لــدى شــرطة اخلبــر وكذلــك‬\n      ‫هيئــة التحقيــق بعــدم جديــة الشــكوى وعــدم إدانــة موكلــي مبــا نســب‬\n      ‫إليــه مــن تهمــه وأن الشــكوى كيديــة ومســتنداتي وبيناتــي مــا يلــي‬\n\n‫‪289‬‬\n\f‫محاضــر التحقيــق وملــف الشــكوى واطلــب اســتدعاء املدعــى عليــه‬\n‫واحلكــم عليــه بالوجــه الشــرعي ملــا بــدر منــه مــن اتهــام موكلــي اتهــام‬\n‫باطــل ال أســاس لــه مــن الصحــة وأن الشــكوى كيديــة كــرد اعتبــار‬\n‫ملوكلــي هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه طلــب مهلــه‬\n‫للــرد علــى دعــوى املدعــي وكالــة وتأجلــت اجللســة ويف يــوم االربعــاء‬\n‫املوافــق ‪1434/1/28‬ه ـ الســاعة التاســعة صباحــا فتحــت اجللســة وقــدم‬\n‫املدعــى عليــه الئحــة جوابــه علــى الدعــوى وهــذا نصهــا‪[ :‬إشــارة لالئحــة‬\n‫الدعــوى املقدمــة مــن املدعــي ضــد املدعــي عليــه فــإن املقــام يقتضــي أن‬\n‫أتقــدم لفضيلتكــم بالــرد علــى تلــك الدعــوى مبــا يلــي ‪ :‬أو ًال ‪ :‬أقــام‬\n‫املدعــي دعــواه اســتنادا علــى شــكواي التــي تقدمــت بهــا لــدى شــرطة‬\n‫اخلبــر بتهديــده وأعتبــر بــأن تلــك الشــكوى كيديــة ونــرد علــى ذلــك بــأن‬\n‫مــن املعلــوم لــدى فضيلتكــم أن حــق رفــع الدعــوى مكفــول لكافــة‬\n‫األفــراد مواطــن كان أم مقيــم دون تفريــق وقــد اســتخدم املدعــي عليــه‬\n‫هــذا احلــق الــذي كفلــه لــه النظــام كمــا أنــه لــم يســيء اســتخدام ذلــك‬\n‫احلــق أو يتعســف يف اســتخدامه ولــم يكــن الهــدف مــن اســتخدامه إحلــاق‬\n‫األذى أو الضــرر باملدعــي بــل كان الهــدف منهــا حمايــة املدعــي عليــه‬\n‫لنفســه مــن تهديــد املدعــي لــه والــذي كان يحتمــل جميــع التفســيرات‬\n‫ومــن ضمنهــا التفســير الــذي فســره املدعــي عليــه ثاني ـ ًا ‪ :‬أن الدعــوى‬\n‫الكيديــة لهــا قواعــد صــادرة مــن مجلــس الــوزراء مباهيتهــا وطــرق‬\n‫معاجلتهــا ولهــا إجــراءات محــددة ومتــى تكــون كيديــة ويحكمهــا‬\n‫القضــاء ‪ ،‬ومت حصرهــا حســب نظــام قواعــد احلــد مــن آثــار الشــكاوى‬\n‫الكيديــة والدعــاوى الباطلــة برقــم ‪ 94‬التاريــخ ‪1406/4/25‬ه ـ يف‬\n‫صنفــن ووضــع لهــا آليــة محــددة لرفعهــا ‪ ،‬الصنــف االول ينطبــق علــى‬\n\n\n                                                                                   ‫‪290‬‬\n\f      ‫مــن أقــام الدعــوى مــع علمــة املســبق بانتهائهــا واكتســاب حكمهــا‬\n      ‫القطعيــة وتقــدمي دعــواه كدعــوى جديــدة ليــس لهــا ســابقة (املــادة‬\n      ‫الثانيــة) وهــو ال ينطبــق علــى هــذه الدعــوى أمــا الصنــف الثانــي فينطبــق‬\n      ‫علــى مــن طلــب اســتئناف النظــر يف دعــوى اكتســبت القطعيــة أو طلــب‬\n      ‫التمــاس إعــادة النظــر فيهــا ولكــن مببــررات أو مســتندات ال ترقــى‬\n      ‫ملســتوى إعــادة النظــر فيهــا وهــذا مــا أشــارت إليــة املــادة الثالثــة مــن‬\n      ‫النظــام وهــي ال تنطبــق علــى هــذه الدعــوى أمــا فيمــا يتعلــق بأليــة رفــع‬\n      ‫تلــك الدعــاوى فنجــد أنــه بالرجــوع إلــى املــادة الرابعــة مــن النظــام جنــد‬\n      ‫أنهــا قــد حــددت تلــك اآلليــة بالنــص علــى أنــه ( مــن تقــدم بدعــوى خاصــة‬\n      ‫وثبــت للمحكمــة كــذب املدعــي يف دعــواه‪ ،‬فللقاضــي أن ينظــر يف‬\n      ‫تعزيــره‪ ،‬وللمدعــي عليــة املطالبــة بالتعويــض عمــا حلقــه مــن ضــرر بســبب‬\n      ‫هــذه الدعــوى) ومبناقشــة املــادة أعــاه جنــد أن قــرار كيديــة الدعــوى‬\n      ‫يجــب أن يصــدر مــن اجلهــة التــي كانــت تنظــر يف الدعــوى األساســية‬\n      ‫متــى مــا ثبــت لــه بالدليــل عــدم صحــة تلــك الدعــوى وهــذا املفهــوم أكــده‬\n      ‫تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪ 86635/16‬يف‬\n      ‫‪1426/10/17‬ه الــذي نــص يف الفقــرة ( ب ) منــه علــى مــا يلــي‪ :‬إحالــة‬\n      ‫جميــع الشــكاوى التــي تــرى اجلهــات احلكوميــة أو األمــارة أنهــا كيديــه‬\n      ‫إلــى هيئــه التحقيــق واالدعــاء العــام للتحقيــق فيهــا وفقـ َا للنظــام ‪ ،‬ورفــع‬\n      ‫الدعــوى أمــام احملكمــة املختصــة للنظــر فيهــا وهنــا يجــب علينــا أن‬\n      ‫نتســاءل هــل قــررت أو توصلــت اجلهــة التــي تولــت التحقيــق يف شــكوى‬\n      ‫املدعــي عليــه ضــد املدعــي إلــى كيديــة تلــك الدعــوى؟ بالرجــوع الــى‬\n      ‫الشــكوى ســالفة الذكــر جنــد أنــه قــد مت حفظهــا لعــدم مراجعــة‬\n      ‫املدعــي ‪ /‬وليــس بســبب كيديــة الدعــوى وبالتالــي فــإن ادعــاء املدعــي‬\n\n\n‫‪291‬‬\n\f‫بــأن تلــك الشــكوى كانــت كيديــة ال أســاس لــه مــن الصحــة ثالثـ ًا ‪ :‬إن‬\n‫واقعــة تهديــد املدعــي للمدعــي عليــه هــي واقعــة حقيقــة لــم يتــم اختالقهــا‬\n‫وأن هنــاك شــهود عليهــا وهــم مســتعدين لــإدالء بشــهادتهم مــرة أخــرى‬\n‫أمــام فضيلتكــم بهــا وال يخفــى علــى فضيلتكــم أن هنــاك فــرق بــن‬\n‫اختــاق واقعــة ليســت موجــودة علــى أرض الواقــع وبــن تكييــف اجلهــات‬\n‫التــي تتولــى التحقيــق أو احملاكمــة لتلــك الواقعــة ويف تلــك الشــكوى‬\n‫التــي يــرى املدعــي كيديتهــا أن املدعــي قــام بتهديــد املدعــي عليــه بعبارة‬\n‫( واهلل مــا أخليــك وهــذا الشــنب مــو علــى رجــال ) ومت تأكيــد ذلــك‬\n‫بشــهادة الشــهود) و( ) والذيــن شــهدا بــأن املدعــي قــام بتهديــد املدعــي‬\n‫عليــه يف قســم الشــرطة بعبــارة ( واهلل مــا راح أخليــه ) وبنــاء علــى ذلــك‬\n‫مت أخــذ التعهــد عليــه مــن قبــل احملقــق بقســم الشــرطة باخلبــر وبنــاء علــى‬\n‫مــا ســبق ذكــره فإننــي ألتمــس من فضيلتكم رد دعــوى املدعي هكذا‬\n‫أجــاب وجــرى ســؤال املدعــى عليــه البينــة علــى مــا ذكــره يف إجابتــه‬\n‫فطلــب إمهالــه إلحضارهــا يف جلســة قادمــة ورفعــت اجللســة لذلــك ويف‬\n‫جلســة اخــرى حضــر أطــراف النــزاع وحضــر للشــهادة مينــي اجلنســية‬\n‫مبوجــب اإلقامــة رقــم وبســؤاله عمــا لديــه قــال إنــه ال يربــط باملدعــى‬\n‫عليــه أي قرابــة وال شــراكة وال عمــل عــدا أن والدتــي تعــرف والدتــه و‬\n‫املدعــي ال أعرفــه و ال يربطنــي بــه ال قرابــة و ال شــراكة و أشــهد هلل‬\n‫تعالــى إنــي ســمعت يقــول يقصــد مــا راح أخليــه ال أنــا والســوري حاطــه يف‬\n‫رأســه وراح اخلــي دموعــه تنــزل دم وراح أقفــل لــه املســتوصف وأفضــح‬\n‫فيــه عنــد النــاس وبعدهــا بيومــن تقريبــا ســمعت هــدد نفــس التهديــد‬\n‫وقــال راح أخلــي دموعــه تنــزل دم وأرد لــه الصــاع صاعــن والســوري‬\n‫حلــف انــه مــا يخليــه بعدهــا انتقلــت معهــم إلى شــرطة اخلبر وثم اســتدعاء‬\n\n\n                                                                                      ‫‪292‬‬\n\f      ‫الســوري فســمعت يقــول للمدعــى عليــه عنــدي مفتــاح اســبير (نســخة‬\n      ‫احتياطيــة) وراح اســحب ســيارتك مــن عنــد املســتوصف حقــك و روح دور‬\n      ‫عليهــا هــذا مــا لــدي وأشــهد بــه هــذا وبطلبــي مــن املدعــى عليــه زيــادة‬\n      ‫بينــة قــال اطلــب إمهالــي ورفعــت اجللســة لذلــك ويف جلســة اخــرى حضــر‬\n      ‫املدعــي وكالــة وحضــر املدعــى عليــه وأحضــر املدعــى عليــه للشــهادة‬\n      ‫احملنــاء ســعودي اجلنســية ســجله املدنــي وبســؤاله عمــا لديــه قــرر قائــا‬\n      ‫إن املدعــى عليــه قــد عملــت معــه يف مكتــب الزقــزوق للعقــار منــذ ســنة‬\n      ‫وحاليــا أعمــل يف مكتــب احملامــي وحاليــا ال يربطنــي باملدعــى عليــه أي‬\n      ‫عالقــة جتاريــة عــدا إنــي توكلــت عنــه يف إحــدى جلســات دعــوى ضــد‬\n      ‫املدعــى عليــه منــذ أكثــر مــن ســتة أشــهر بصفتــي موظــف مبكتــب‬\n      ‫احملامــي وكيــل املدعــى عليــه هكــذا قــرر وبســؤاله عمــا لديــه مــن‬\n      ‫شــهادة قــرر قائــا أشــهد هلل تعالــى إنــي كنــت يف شــرطة اخلبــر مــع‬\n      ‫وتواجدنــا يف مقــر الشــرطة بشــأن موضــوع ســيارة نــوع رجن موديل ‪2008‬م‬\n      ‫تعــود ملكيتهــا للمدعــى عليــه وقــد أخذهــا مــن املدعــى عليــه بالشــراء‬\n      ‫باألقســاط وكان تواجدنا أساســا بالشــرطة بســبب اخلالف يف موضوع‬\n      ‫الســيارة بــن وكان أيضــا بالشــرطة ثــم حضر للشــرطة وكان متواجدا‬\n      ‫فحصــل بينهمــا كالم بخصــوص ســحب الســيارة ‪ ...‬موديــل ‪ 2008‬فــرد‬\n      ‫‪ .........‬قائــا الســيارة اإلكــس إكــس راح اســحبها عنــدي مفتــاح‬\n      ‫األســبير وهــو يقصــد ســيارة بــي أم دبليــو اشــتراها املدعــى عليــه مــن‬\n      ‫فقــام يناظــر يف املدعــى عليــه وقــال لــه واهلل مــا أخليــك طيــب وأخلــي‬\n      ‫دموعــك تبكــي دم والشــوارب مــو علــى رجــال هــذا مــا لــدي وأشــهد بــه‬\n      ‫هــذا وقــرر وكيــل املدعــي قائــا أطلــب ســؤال الشــاهد عــن أيــن كان‬\n      ‫موجــودا أثنــاء الواقعــة محــل الشــهادة وأيــن وجــود أطــراف النــزاع وأيــن‬\n\n\n‫‪293‬‬\n\f‫مــكان الشــاهد األول هكــذا قــرر وبعــرض ذلــك علــى الشــاهد قــرر‬\n‫قائــا كنــا جمعيــا يف اســتقبال شــرطة اخلبــر وأنــا كنــت مــن اجلهــة‬\n‫اليســرى ومعــي وأمــا كان واقفــا يف اجلهــة اليمنــى والبــس ثــوب شــتوي‬\n‫لونــه أزرق هــذا وحضــر الشــاهد األول وجــرى ســؤاله نفــس الســؤال‬\n‫الســابق املوجــه مــن الوكيــل فأجــاب قائــا كنــت جالســا علــى‬\n‫الكراســي يف الــدور األرضــي أنــا واملدعــى عليــه والشــاهد‪ -‬كان‬\n‫موجــودا بنفــس املــكان لكنــه كان واقفــا و الواقعــة معــي عليــه فتــرة‬\n‫طويلــة وال أتذكــر تفاصيلهــا وأظــن انــه كان ليــس ثــوب وال أتذكــر‬\n‫لونــه بالتحديــد وأظــن لونــه أبيــض وأثنــاء ذلــك جــاء فتقابــل مــع وحصــل‬\n‫بينهمــا كالم وســمعة يقــول خليــه خليــه وكان يؤشــر علــى ‪ ....‬قائــا‬\n‫راح أســحب ال بــي ام اكــس ســكس اســحبه مــن قــدام املســتوصف‬\n‫ألنــي عنــدي مفتــاح أســبير ومــا أراح أخليــك طيــب وراح أخلــي دموعــك‬\n‫تنــزل دم وهــذه الشــوارب مــو علــى رجــال هــذا مــا لــدي وأشــهد بــه هــذا‬\n‫وبعــرض الشــهود و شــهادتهم علــى املدعــي وكالــة قــال أطلــب إمهالــي‬\n‫ورفعــت اجللســة لذلــك ويف جلســة اخــرى حضــر املدعــي وكالــة ولــم‬\n‫يحضــر املدعــي اصالــة وال مــن ميثلــه شــرعا حتــى انتهــاء وقــت اجللســة‬\n‫احملــدد بهــذا اليــوم الســاعة الثامنــة والربــع وتأجلــت اجللســة للتأمــل ويف‬\n‫جلســة اخــرى حضــر املدعــي وكالــة و املدعــى عليــه هــذا وبالرجــوع إلــى‬\n‫أوراق املعاملــة جــرى االطــاع علــى اآلتــي‪ ]1[ :‬بــاغ املدعــى عليــه علــى‬\n‫ملــف التحقيــق (لفــة ‪ 1‬صفحــة‪ )10‬و املتضمــن‪ { :‬أن ‪ ...‬يهــدده بالقتــل و‬\n‫بســحب ســيارته وبســؤاله هــل لــه شــركاء أجــاب نعــم شــخص ســوري‬\n‫يدعــى} [‪ ]2‬محضــر تفريــغ رســالة علــى ملــف التحقيــق (لفــة ‪ 1‬صفحــة‬\n‫‪ )13‬املتضمــن جــرى تفريــغ رســالة وصلــت مــن املدعــو إلــى املدعــو عــن‬\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫طريــق خدمــة البــاك بيــري ونــص احلاجــة منــه { أنــت تعرفنــي أنــا إنســان‬\n      ‫أتــرزق تبونــي أشــهد معكــم الصراحــة بــدون إحــراج بأخــذ اتعــاب إذا‬\n      ‫بتعطونــي ثالثــة آالف ريــال بأشــهد معكــم } [‪ ]3‬أقــوال علــى ملــف‬\n      ‫التحقيــق (لفــة ‪ 10‬صفحــة ‪ )1‬ونــص احلاجــة منهــا { ســؤال‪ :‬يوجــد رســالة‬\n      ‫أرســلتها عــن طريــق بــاك بيــري مســنجر مفادهــا أنــك تريــد أن تشــهد و‬\n      ‫تأخــذ أتعــاب؟ جــواب‪ :‬نعــم أرســلتها بعدمــا أرســل لــي ؛ ســؤال‪ :‬أيــن‬\n      ‫الرســالة التــي أرســلها لــك ؟ جــواب‪ :‬كانــت عنــدي علــى البــاك بيــري‬\n      ‫ثــم حذفنــي مــن البــاك بيــري؛ ســؤال‪ :‬هــذه الرســالة تخــص أي شــهادة؟‬\n      ‫جــواب‪ :‬الشــهادة علــى بيــع الســيارة و علــى الرشــوة التــي قدمهــا لــي ؛‬\n      ‫ســؤال‪ :‬هــل لديــك مــا يثبــت أنــه قــدم لــك رشــوة؟ جــواب‪ :‬ال} [‪ ]4‬أقــوال‬\n      ‫املدعــى عليــه علــى ملــف التحقيــق (لفــة‪ 10‬صفحــة ‪ )1‬ونــص احلاجــة منــه‬\n      ‫{ســؤال‪ :‬مــا نــوع التهديــد؟ جــواب‪ :‬الــذي هددنــي فقــط هــو حيــث قــام‬\n      ‫باالتصــال علــي وقــال إذا لــم تتنــازل عــن القضيــة يف شــرطة الدمــام‬\n      ‫فســوف أقــوم بقتلــك؛ ســؤال‪ :‬هــل قــام بتهديــدك؟ جــواب‪ :‬نعــم قــام‬\n      ‫بتهديــدي بالقتــل عــن طريــق هــذا و أبــرز املدعــي وكالــة صحيفــة نصهــا‬\n      ‫بــكل مــا يســتوجب االحتــرام والتقديــر ملقــام فضيلتكــم وبصفتنــا‬\n      ‫الــوكالء الشــرعيون عــن املدعــى ‪ /‬أتقــدم لفضيلتكــم بهــذه املذكــرة‬\n      ‫اجلوابيــة علــي رد املدعــى عليــه وأقــوال شــاهديه يف الدعــوى املقيــدة أمــام‬\n      ‫محكمتكــم املوقــرة برقــم ‪ 332141993‬وتاريــخ ‪ 1433/11/29‬ه ـ‬\n      ‫آملــن تكــرم فضيلتكــم بتوقيــع أقســى اجلــزاء علــى املدعــى عليــه‬\n      ‫وحتريــر دعــوى جزائيــة يف مواجهــة الشــهود لــإدالء بشــهادة الــزور أمــام‬\n      ‫احملكمــة وذلــك لألســباب اآلتيــة ‪ :‬أو ًال ‪:‬فإن الشــريعة اإلســامية جاءت‬\n                                                 ‫باإلنصــاف والعــدل فقــال عــز وجــل‪ِ ( :‬إ َّن َّ َ‬\n      ‫الل َي ْأ ُمـ ُـر ِبا ْل َعــدْ لِ واإلحســان)‬\n\n\n‫‪295‬‬\n\f‫‪ ،‬وحرمــت الشــريعة اإلســامية الظلــم والعــدوان ملــا روى أبــو ذر رضــي‬\n‫اهلل عنــه عــن النبــي صلــى اهلل عليــه وســلم فيمــا يرويــه عــن ربــه عــز وجــل‬\n‫أنــه قــال ‪ ( :‬يــا عبــادي إنــي حرمــت الظلــم علــى نفســي وجعلتــه بينكــم‬\n‫محرم ـ ًا فــا تظاملــوا) ومــن ذلــك حتــرمي اإلضــرار باآلخريــن واالعتــداء‬\n‫عليهــم مــن خــال مخاصمتهــم بالباطــل واالدعــاء عليهــم بغيــر حــق‬\n‫كذب ـ ًا وبهتان ـ ًا ‪ ،‬ومــا حرمــت الشــريعة اإلســامية الظلــم والعــدوان إال‬\n‫ملــا فيهمــا مــن إحلــاق الضــرر باألبريــاء واتهامهــم مبــا هــم بــراء منــه ومــا‬\n‫يترتــب علــى ذلــك مــن إشــغال للجهــاز القضائــي واجلهــات احلكوميــة‬\n‫ذات العالقــة بهــذه القضايــا ولقــد تعــرض فقهاؤنــا رحمهــم اهلل تعالــى‬\n‫ألحــكام هــذه الدعــاوى الباطلــة والكيديــة فأبانــوا حكمهــا وعقوبتها‬\n‫والتعويــض عــن الضــرر الــذي يلحــق املدعــى عليــه بســببها مبــا يكفــل‬\n‫منعهــا أو احلــد منهــا وحفاظ ـ ًا علــى النفــوس واألمــوال ومنع ـ ًا للظلــم‬\n‫والعــدوان وردع ـ ًا للمعتديــن وجــاء تعريفهــم للدعــوى الكيديــة بأنهــا‬\n‫مطالبــة املدعــى غيــره بأمــر ال حــق لــه فيــه وبغيــر وجــه حــق مــع علمــه‬\n‫بذلــك وقياس ـ ًا علــى مــا ذكــر بعاليــه فــإن مــا قــام بــه املدعــى عليــه ‪/‬‬\n‫أمــام هيئــة التحقيــق واالدعــاء العــام يف مواجهــة ينطبــق عليــه وصــف‬\n‫الدعــوى الكيديــة وذلــك لثبــوت براءتــه ممــا نســب إليــه مــن تهديــد‬\n‫املدعــى عليــه ‪ /‬وإال ملــاذا ردت هيئــة التحقيــق واالدعــاء العــام دعــوى‬\n‫ضــد ؛ ثانيـ ًا ‪ :‬لقــد كانــت شــكوى ضــد أمــام هيئــة التحقيــق واالدعــاء‬\n‫العــام بســبب أن قــد هــدده بالقتــل وبعــد التحريــات معــه ومــع شــهوده‬\n‫والذيــن لــم يشــهدوا لــه بواقعــة التهديــد بالقتــل تــرك دعــواه ‪،‬وعنــد‬\n‫اســتجوابه بخصــوص الدعــوى الكيديــة التــي أقامهــا ضــد عــاد وقــال‬\n‫أن اتصــل بــه علــى جوالــه وقــام بالتهديــد بأنــه ســوف ينتقــم منــه وكان‬\n\n\n                                                                                          ‫‪296‬‬\n\f      ‫التهديــد مقصــود بــه القتــل وعندمــا لــم يثبــت التهديــد بالقتــل أمــام هيئــة‬\n      ‫التحقيــق واالدعــاء العــام عــاد وصــاغ الشــكوى مــرة أخــرى بألفــاظ غيــر‬\n      ‫التهديــد بالقتــل مثــل ( حأخلــي دموعــك تنــزل دم وأقفــل املســتوصف )‬\n      ‫وهــذا بينــة علــى أن دعــوى كانــت كيديــة ألنــه أراد بذلــك اتهــام مبــا‬\n      ‫هــو بــراء منــه ‪ ،‬و الدعــوى املنظــورة اآلن أمــام فضيلتكــم واملقامــة مــن‬\n      ‫املدعــى ‪ /‬ضــد املدعــى عليــه ‪ /‬هــي لــرد اعتبــار املدعــى لكونــه اتهــم‬\n      ‫بتهديــد املدعــى عليــه بالقتــل زور ًا وبهتانـ ًا وكيــد ًا بــه إلحلــاق الضــرر بــه‬\n      ‫واالعتــداء عليــه مــن خــال مخاصمتــه بالباطــل واالدعــاء عليــه بغيــر حــق‬\n      ‫كذب ـ ًا وبهتان ـ ًا ‪ ،‬وهــذا مــا حرمتــه الشــريعة اإلســامية ‪ ،‬أمــا كــون‬\n      ‫األلفــاظ التــي صــدرت بلفــظ ( أخلــي دموعــه تنــزل دم وراح أقفــل‬\n      ‫املســتوصف ) فــإن مثــل هــذه األلفــاظ ال ترقــى ملســتوى التهديــد بالقتــل‬\n      ‫ا أن عنــد ادعائــه بأنــه مت تهديــده بالقتــل قــال‬     ‫الــذي يدعيــه ‪ ،‬هــذا فضـ ً‬\n      ‫أن التهديــد الــذي وقــع عليــه عــن طريــق االتصــال الهاتفــي علــى جوالــه‬\n      ‫يف حــن جــاءت شــهادة الشــاهدين بــأن التهديــد وقــع بشــكل مباشــر‬\n      ‫وكان أمامهــم وأمــام يف مركــز شــرطة اخلبــر ولــو أطلــع فضيلتكــم‬\n      ‫علــى محاضــر التحقيــق لوجــد تضــارب األقــوال بحيــث أن املدعــى عليــه‬\n      ‫أقــر يف تاريــخ ‪1433/06/14‬ه ـ بــأن التهديــد يف مركــز الشــرطة كان‬\n      ‫مــن فقــط وأن الســوري لــم يذكــر ســوى أنــه ســوف يقــوم بســحب‬\n      ‫الســيارة لوجــود مفتــاح إضــايف لديــه ‪ ،‬وهنــا الســؤال كيــف ســمع‬\n      ‫الشــهود تهديــد الســوري ؟ ثالثـ ًا ‪ :‬بالرجــوع إلــى أقــوال شــاهدي املدعــى‬\n      ‫عليــه جنــد أن أقوالهمــا قــد شــابها التضــارب ولــم تتطابــق مــع بعضهــا‬\n      ‫وذلــك حيــث شــهد الشــاهد األول‪ ......‬إلــى آخــره ثــم قــال بعــد يومــن‬\n      ‫ســمعت هــدد نفــس التهديــد إلــى آخــره والســوري حاطــه يف رأســه إلــى‬\n\n\n‫‪297‬‬\n\f‫آخــره ‪ ،‬وكان ذلــك يف جلســة يــوم األحــد ‪ 1434/2/24‬ه ـ ثــم جــاء‬\n‫نفــس الشــاهد وهــو يف جلســة يــوم األربعــاء املوافــق ‪ 1434/3/25‬ه ـ‬\n‫وقــال أنــه ســمع قــد هــدد وبالتمعــن يف هــذه الشــهادة والتدقيــق فيهــا‬\n‫جندهــا قــد جــاءت متضاربــة ومختلفــة متامـ ًا وهي لشــاهد واحــد وبالتالي‬\n‫تكون هذه الشــهادة شــهادة زور وكاذبة يف حق املدعى ‪ /‬ألن الشــاهد‬\n‫أراد كذبـ ًا وبهتانـ ًا اإلضــرار باملدعــى ‪ /‬أمــا إذا متعنــا يف شــهادة الشــاهد‬\n‫الثانــي فقــد شــهد يف محاضــر التحقيــق أمــام شــرطة اخلبــر بــأن الــذي‬\n‫هــدد هــو وعندمــا ســأله احملقــق عمــا إذا كان قــد ســمع هــدد أمامــه ؟‬\n‫أجــاب علــى ســؤال احملقــق وقــال ‪ :‬ال ‪ ،‬ثــم جــاء أمــام فضيلتكــم ويف‬\n‫جلســة يــوم األربعــاء ‪ 1434/3/25‬ه ـ وشــهد بــأن هــدد ويف هــذا أيض ـ ًا‬\n‫اختــاف وتضــارب يف أقــوال هــذا الشــاهد والتــي جــرت يف نفــس‬\n‫املوضــوع ‪ ،‬وتعلمــون فضيلتكــم القاعــدة النظاميــة التــي تقــول أنــه إذا‬\n‫تضاربــت أقــوال الشــهود كان ذلــك برهانــا علــى بطــان االدعاء أساسـ ًا‬\n‫‪ ،‬هــذا باإلضافــة إلــى أن الشــاهدين اختلفــا أيض ـ ًا يف اإلجابــة علــى‬\n‫ســؤال وكيــل املدعــى الــذي وجــه إليهمــا فقــد ذكــر الشــاهد األول أن‬\n‫‪ ....‬كان يرتــدي ثوب ـ ًا صيفــي ابيــض اللــون يف حــن ذكــر الشــاهد‬\n‫الثانــي أن ‪....‬كان يرتــدي ثوب ـ ًا شــتويا ازرق اللــون وهــذا أيض ـ ًا يعتبــر‬\n‫ا علــى أن شــهادة الشــاهدين كانــت شــهادة زور قصــد منهــا‬                 ‫دلي ـ ً‬\n‫اإلضــرار باملدعــى كمــا أن الشــاهد الثانــي يعتبــر شــاهد مصلحــة فقــد‬\n‫ذكــر يف أقوالــه أنــه عمــل مــع املدعــى عليــه ‪ /‬يف مكتــب عقــارات‬\n‫ا لــه يف دعــوى ضــد وهــذه الدعــوى مــا زالــت‬      ‫كمــا أنــه كان وكي ـ ً‬\n‫منظــورة أمــام فضيلتكــم وبالتالــي يجــب رد شــهادة الشــاهد لتوفــر‬\n‫املصلحــة فقــد قــال رســول اهلل صلــى اهلل عليــه وســلم ‪ ( :‬ال تقبــل شــهادة‬\n\n\n                                                                                        ‫‪298‬‬\n\f      ‫الظنــن وذي املصلحــة ) رابعـ ًا ‪ :‬لقــد ثبــت أمــام احملقــق يف هيئــة التحقيــق‬\n      ‫واالدعــاء العــام ومــن خــال مــا مت ضبطــه باحملضــر يف صفحــة (‪ )6‬مــن‬\n      ‫الشــكوى التــي تقــدم بهــا ضــد أن مت الكشــف عــن فحــوى رســالة‬\n      ‫صــادرة مــن جــوال الشــاهد البــاك بيــري ومضمــون هــذه الرســالة أن‬\n      ‫طلــب منــح مبلــغ ‪ 3000‬ريــال حتــى يشــهد معــه ومــع ويســلمهم صــوره‬\n      ‫اإلقامــة اخلاصــة بــه لكتابــة مــا يريــدون ثــم يقــوم هــو بالتوقيــع عليهــا و‬\n      ‫الشــهادة علــى صحتهــا وعنــد عــرض هــذا الــكالم علــى الشــاهد أقــر‬\n      ‫بفحــوى الرســالة وهــذا إن دل علــى شــيء إمنــا يــدل علــى أن هــذا الشــاهد‬\n      ‫هــو شــاهد زور وميكنــه أن يشــهد كذبـ ًا وبهتانـ ًا متــى مــا أعطــي املقابــل‬\n      ‫املــادي الــذي يطلبــه خامسـ ًا ‪:‬كذلــك فــإن الشــاهد األول يف جلســة يــوم‬\n      ‫األحــد بتاريــخ ‪1433/02/24‬ه ـ ذكــر يف بدايــة شــهادته بأنــه ال يربطــه‬\n      ‫باملدعــى عليــه (‪ )....‬ال قرابــة و ال شــراكه وال عمــل ‪ ،‬عــدا أن والدتــه‬\n      ‫تعــرف والــدة املدعــى عليــه‪ .‬وبالرجــوع إلــى محاضــر التحقيــق لــدى هيئــة‬\n      ‫التحقيــق واالدعــاء العــام يف صفحــه رقــم ( ‪ ) 6‬ذكــر الشــاهد بــأن‬\n      ‫عالقتــه باملدعــى عليــه (‪ )....‬بالنــص التالــي ( بينــي وبينــه جتــاره ســيارات‬\n      ‫)‪ .‬وهــذا تضــارب يف أقوالــه وعــدم مصداقيتــه فكيــف تقبــل شــهادة ذي‬\n      ‫املصلحــة وكاذب يف نفــس الوقــت سادس ـاً‪ :‬عليــه وملــا ذكرنــا بعاليــه‬\n      ‫فإننــا نلتمــس مــن فضيلتكــم التكــرم مبحاســبة املدعى عليــه ‪ /‬وتوقيع‬\n      ‫أقســى اجلــزاءات عليــه ‪ -‬وكذلــك محاســبة شــاهديه لكونهمــا شــهدا‬\n      ‫شــهادة الــزور وذلــك مــن خــال مــا ذكرنــاه بعاليــه ‪ ،‬يكــون جــزاء‬\n      ‫شــهادة الــزور عنــد اهلل تعالــى إذا لــم تتــب يف حياتــك فهــو جــزاء أهــل‬\n      ‫الكبائــر إذا ماتــوا قبــل التوبــة فــإن شــاء عذبهــم وإن شــاء عفــا عنهــم‬\n      ‫هــذا فيمــا يتعلــق بحــق اهلل تعالــى ‪ ،‬أمــا حقــوق العبــاد وهــي التــي‬\n\n\n‫‪299‬‬\n\f‫نقصدهــا هنــا ونطلــب تطبيقهــا يف مواجهــة الشــاهدين فأولهــا التوبــة‬\n‫ويشــترط للتوبــة منهــا اســتحاللهم يف الدنيــا كمــا أنهــا تســتحق التعزيــر‬\n‫مــن قبــل القاضــي بالضــرب أو احلبــس ونحــوه علــى حســب مــا يــرى ممــا‬\n‫تقتضيــه املصلحــة ‪ ،‬قــال النــووي يف روضــة الطالبــن ‪ :‬وقــد صــرح‬\n‫صاحــب املهــذب بذلــك يف شــهادة الــزور فقــال التوبــة منهــا أن يقــول‬\n‫كذبــت فيمــا فعلــت وال أعــود إلــى مثلــه هكــذا قــرر فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى و اإلجابــة و حيــث أن الشــاهدين محــل تهمــة حيــث أن‬\n‫أحدهمــا تضمــن إقــراره حتقيقــا أنــه طلــب مبلــغ مقابــل الشــهادة و حيــث‬\n‫أن الشــاهد الثانــي كان يعمــل لــدى املدعــى عليــه و تــوكل عنــه يف‬\n‫قضيــة و كل هــذه تهــم تضعــف قبــول الشــهادة إال أن تفريــق الشــاهدين‬\n‫بنــاء علــى طلــب وكيــل املدعــي و تطابــق شــهادتهما يف تفاصيــل مهمــة‬\n‫تــورث شــبهة يف تعــرض املدعــى عليــه للتهديــد ممــا يجعــل املدعــى عليــه‬\n‫هــو أقــوى جانبــا مــن املدعــي أصالــة كمــا أنــه ليــس كل دعــوى ليــس‬\n‫عليهــا إثبــات تعــد دعــوى كيديــة فقد يدعي الشــخص بدعــوى صحيحة‬\n‫وال يســتطيع اإلثبــات لــذا و ألن األصــل هــو بــراءة الذمــة وألن اليمــن‬\n‫تشــرع يف جانــب أقــوى املتداعيــن لــذا أفهمــت املدعــى عليــه أنــه يلزمــه‬\n‫اليمــن علــى أنــه تعــرض للتهديــد بالقتــل مــن املدعــي فاســتعد بذلــك‬\n‫وحلــف قائــا واهلل العظيــم الــذي ال إلــه إال هــو احلــي القيــوم عالــم الغيــب‬\n‫و الشــهادة أن املدعــي أصالــة هددنــي بعبــارة (واهلل مــا راح أخليــه) و‬\n‫بعبــارة ( واهلل مــا أخليــك وهــذا الشــنب مــو علــى رجــال ) وقــد فهمــت مــن‬\n‫هــذا التهديــد هــو التهديــد بالقتــل واهلل العظيــم أن شــكواي ضــده‬\n‫ليســت كيديــة ولــم أقصــد إحلــاق الضــرر بــه هكــذا حلف لــذا حكمت‬\n‫بعــدم اســتحقاق املدعــي ملــا يطالــب بــه مــن عقوبــة للمدعــى عليــه لعــدم‬\n\n\n                                                                                       ‫‪300‬‬\n\f      ‫ثبــوت موجبهــا وبعــرض احلكــم عليــه قــرر املعارضــة و طلــب اســتئناف‬\n      ‫احلكــم فأجبتــه لطلبــه و أفهمتــه باملراجعــة بتاريــخ ‪1434/5/28‬ه ـ‬\n      ‫الســتالم صــورة مــن القــرار الشــرعي وجــرى إفهامــه بتعليمــات اســتئناف‬\n      ‫األحــكام الشــرعية وصلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم‬\n                                                           ‫حرر يف ‪1434/5/21‬هـ‬\n\n\n\n\n‫‪301‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":288,"source_page_end":301,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44f91c59800ee61e12379cc604103547dc98d3a43990de9322ab1521aa5f7eca","normalized_text_hash":"be02ef53e1b221254a96baafb3dc6d3abb5767de086a21cd3383aebdbf69f169","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p288-332141993"},{"id":"84b8de23-eaa1-5e24-8548-ccf08624f003","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب والتلفظ -مطالبة املدعي باملجازاة -سابقة الفصل يف الدعوى بحكم نهائي -ثبوت كيدية الدعوى -رد الدعوى -تعزير املدعي بنكال.","document_number":"34265082","case_number":"33698823","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/11","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب والتلفظ -مطالبة املدعي باملجازاة -سابقة الفصل يف الدعوى بحكم نهائي -ثبوت كيدية الدعوى -رد الدعوى -تعزير املدعي بنكال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34265082 :‬‬\n                   ‫َر ْق ُم الدعوى‪33698823 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 33321790‬تاريخه‪1434/6/30 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب والتلفــظ ‪ -‬مطالبــة‬\n‫املدعــي باملجــازاة ‪ -‬ســابقة الفصــل يف الدعــوى بحكــم نهائــي ‪ -‬ثبــوت‬\n              ‫كيديــة الدعــوى ‪ -‬رد الدعــوى ‪ -‬تعزيــر املدعــي بنــكال‪.‬‬\n\n\n\n\n       ‫الفقرة (‪ )4/5‬من الالئحة التنفيذية لنظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه احلاضــر قــام باالعتــداء عليــه وذلــك‬\n‫بضربــه والتلفــظ عليــه وتصويــره علــى إثــر خــاف بينهمــا‪ ،‬ولــذا فقــد‬\n‫طلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه‬\n‫مــا جــاء يف الدعــوى جملــة وتفصيــا ودفــع بأنــه صــدر حكــم نهائــي‬\n‫لصاحلــه يف دعــوى مماثلــة تقــدم بهــا املدعــي ضــده قبــل هــذه الدعــوى‪-‬‬\n‫أقــر املدعــي بصحــة مــا دفــع بــه املدعــى عليــه كمــا حتققــت احملكمــة‬\n‫مــن ذلــك باالطــاع علــى احلكــم الســابق‪ -‬املدعــي ُيطالــب بحــق حكــم‬\n‫فيــه لصالــح املدعــى عليــه بحكــم نهائــي ممــا يــدل علــى أن دعــواه‬\n‫كيديــة‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي لســبق الفصــل فيهــا‬\n‫بحكــم نهائــي وقــررت جلــده أربعــن جلــدة دفعــة واحــدة علنــا وأخــذ‬\n‫التعهــد عليــه بعــدم العــودة ملثــل مــا بــدر منــه مســتقبال لقــاء تقدميــه دعــوى‬\n\n                                                                                           ‫‪302‬‬\n\f      ‫كيديــة‪ -‬عــارض املدعــي علــى احلكــم وقنــع بــه املدعــى عليــه‪ -‬قــررت‬\n                                   ‫محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫فلدي أنا‬\n           ‫ّ‬        ‫احلمد هلل وحده والصالة والســام على من ال نبي بعده وبعد‪،‬‬\n      ‫‪ .....‬القاضــي باحملكمــة اجلزئيــة باملدينــة حــا ًال بنــاء علــى املعاملــة املقيــدة‬\n      ‫بأســاس هــذه احملكمــة رقــم ‪ 332220120‬وتاريــخ ‪1433/12/22‬ه ـ‬\n      ‫واحملالــة مــن رئيــس احملكمــة باإلحالــة رقــم ‪ 33698823‬وتاريــخ‬\n      ‫‪1433/12/22‬ه ـ عليــه يف هــذا اليــوم االثنــن املوافــق ‪1434/6/26‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة صباح ـاً‪ ،‬وفيهــا حضــر املدعــي‬\n      ‫املواطــن (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...‬ضــد‬\n      ‫املدعــى عليــه املقيــم ‪ /‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)...‬‬\n      ‫قائــا يف حتريــر دعــواه عليــه أننــي ســبق وأن أقمــت دعــوى لــدى هــذه‬\n      ‫احملكمــة بالقيــد األساســي رقــم(‪ )321186404‬ضــد املــرأة ‪ /‬ســعودية‬\n      ‫اجلنســية مببلــغ وقــدره تســعة األف وخمســمائة ريــال باقــي أجــرة شــقة‬\n      ‫اســتأجرتها منــي يف عمارتــي الواقعــة يف ‪ ......‬باملدينــة وقد حضرت املرأة‬\n      ‫لــدى احلاكــم الشــرعي وأقــرت أنهــا ســلمت جــزء مــن املبلــغ للمدعــى‬\n      ‫عليــه هــذا احلاضــر ثــم حضــر املدعــى عليــه لــدى احلاكــم الشــرعي وأقــر‬\n      ‫باســتالمه للمبلــغ الــذي ذكرتــه املــرأة وقــدره ثمانيــة األف وأربعمائــة‬\n      ‫وخمســون ريــا ًال وقــد حكــم القاضــي علــى املــرأة بدفــع مــا أقــرت بــه‬\n      ‫وهــو جــزء بســيط وقــدره الــف وخمســون ريــا ًال وأفهمنــي بالرجــوع علــى‬\n      ‫املدعــى عليــه يف مــا أقــر باســتالمه مــن املــرأة هكــذا حكــم القاضــي‬\n      ‫مبوجــب الصــك رقــم (‪ )32263349‬وتاريــخ ‪1432/10/15‬ه ـ ثــم بعــد‬\n\n‫‪303‬‬\n\f‫ذلــك حضــرت للمدعــى عليــه يف مكتبــه بتاريــخ األربعــاء املوافــق‬\n‫‪1433/4/14‬ه ـ وهنــاك اعتــدى علـ ّـي املدعــى عليــه بالضــرب وأغلــق‬\n‫محلــه علـ ّـي وقــام بتصويــري وقــام بالتلفــظ علـ ّـي‪ ،‬لــذا أطلــب احلكــم‬\n‫عليــه بالوجــه الشــرعي وتأديبــه هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه‬\n‫ا نعــم صحيــح مــا ذكــره احلاكــم الشــرعي بالصــك املشــار‬       ‫أجــاب قائـ ً‬\n‫إلــى رقمــه يف دعــوى املدعــي وبالنســبة حلضــور املدعــي لــي يف مقــر عملــي‬\n‫نعــم هــذا صحيــح حضــر لدينــا بالتاريــخ املشــار إليــه وقــد تهجم هــو علينا‬\n‫وأعتــدى علــى املكتــب والعاملــن وقــد مت التحقيــق معــه لــدى الشــرطة‬\n‫وهيئــة التحقيــق وأديــن بهــذه القضيــة للحــق العــام وأحيــل للمحكمــة‬\n‫هنــا وحكــم عليــه لــدى الشــيخ بالســجن واجللــد ولــم نعتــد عليــه ابتــداء‬\n‫واطلــب الكتابــة للشــيخ للتأكــد مــن ذلــك وبعــرض ذلــك علــى املدعــي‬\n‫علي الشــيخ هداه اهلل بســبب ذهابي‬     ‫ا نعــم صحيــح لقــد حكــم ّ‬    ‫قــرر قائـ ً‬\n‫ملقــر عمــل املدعــى عليــه ولــم أدر أن املدعــى عليــه قــد دبـ ّـر لــي مكيــدة‬\n‫وال أقــول إال حســبي اهلل ونعــم الوكيــل‪ ،‬فجــرى رفــع اجللســة للكتابــة‬\n‫للقاضــي بهــذه احملكمــة الشــيخ للتأكــد مــن ذلــك‪ ،‬ويف جلســة أخــرى‬\n‫حضــر الطرفــان املدعــي واملدعــى عليــه وجــرى مواصلــة نظــر الدعــوى‬\n‫وقــد جــرى منــي ســابقا الكتابــة لفضيلــة احلاكــم الشــرعي بهــذه‬\n‫احملكمــة القاضــي بخطابــي رقــم ‪ 341147411‬وتاريــخ ‪1434/5/8‬ه ـ‬\n‫لإلفــادة عمــا ذكــره املدعــى عليه بإجابته أعــاه فوردنا خطاب فضيلته‬\n‫باخلطــاب رقــم ‪ 341147411‬وتاريــخ ‪1434/05/20‬هــت واملتضمــن مــا‬\n‫نصــه بعــد املقدمــة (حيــث صــدر منــا القــرار الشــرعي رقــم ‪33321790‬‬\n‫يف ‪1433/06/30‬ه ـ واحملكــوم فيــه للحقــن العــام واخلــاص ضــد ‪/‬‬\n‫(‪ ).....‬كمــا صــدر منــا القــرار الشــرعي ‪ 33263790‬يف ‪1433/5/24‬هـ‬\n\n\n                                                                                      ‫‪304‬‬\n\f      ‫واملتعلقــة بدعــوى ‪ ).....( /‬ضــد ‪ ).....( /‬وقــد أكتســب القــرارات‬\n      ‫القطعيــة بتصديقــه مــن محكمــة االســتئناف مبكــة املكرمــة ولــم‬\n      ‫يعــد للمذكوريــن أي دعــوى عندنــا ســوى مــا ذكــر ) ا‪ .‬ه ـ وقــد أرفــق‬\n      ‫احلاكــم الشــرعي بخطابــه ســالف الذكــر صــورة مصدقــة مــن القــرار‬\n      ‫الشــرعي رقــم ‪ 33321790‬وتاريــخ ‪1433/06/30‬ه ـ واملتضمــن ( دعــوى‬\n      ‫املدعــي العــام ضــد املدعــي هنــا واملتضمــن اتهامــه بالتهجــم علــى ‪ /‬يف‬\n      ‫مكتبــه ورميــه مبجموعــة مــن املفاتيــح واملنتهــي القــرار باحلكــم علــى‬\n      ‫املدعــي للحــق العــام واخلــاص بجلــده ســبعني جلــده وســجنه عشــرين يومــا‬\n      ‫وأخــذ التعهــد عليــه واملصــدق عليــه مــن محكمــة االســتئناف بالقــرار‬\n      ‫رقــم ‪ 33434805‬وتاريــخ ‪1433/10/23‬ه ـ ) ثــم جــرى أيضــا االطــاع‬\n      ‫علــى صــورة القــرار الشــرعي الصــادر مــن احلاكــم الشــرعي املذكــور‬\n      ‫برقــم ‪ 33263790‬وتاريــخ ‪1433/05/24‬ه ـ واملتضمــن (دعــوى املدعــي‬\n      ‫هنــا ‪ /‬ضــد املدعــى عليــه هنــا ‪ /‬بذهــاب املدعــي ملقــر عمــل املدعــى عليــه‬\n      ‫وقيــام املدعــى عليــه بالتلفــظ علــى املدعــي بالسـ ّـب والشــتم واللعــن ودفعه‬\n      ‫بيــده وضربــه علــى صــدره وإحلــاق األذى بــه واملطالــب بتأديــب املدعــى‬\n      ‫عليــه لقــاء مــا بــدر منــه وقــد انتهــى القــرار بعــدم ثبــوت دعــوى املدعــي‬\n      ‫ضــد املدعــى عليــه وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‬\n      ‫واملصــدق مــن محكمــة االســتئناف بالقــرار رقــم ‪ 33282327‬وتاريــخ‬\n      ‫‪1433/06/04‬ه ـ ) هــذا مــا تضمنــه خطــاب فضيلــة احلاكــم الشــرعي‬\n      ‫مفصــا‪ ،‬وبعــرض ذلــك علــى الطرفــن وســؤال املدعــي هــل االعتــداء‬\n      ‫عليــك املذكــور بدعــواك هنــا هــو نفســه االعتــداء املنتهــي بالصكــن‬\n      ‫ا نعــم هــو نفســه‪ ،‬ثــم جــرى االطــاع علــى اإلحالــة لهــذه‬ ‫أعــاه قــرر قائـ ً‬\n      ‫ـدي فأتضــح أنهــا محالــة مــن شــرطة العقيــق وأحيلــت ملكتبــي‬    ‫املعاملــة لـ ّ‬\n\n‫‪305‬‬\n\f‫برقــم ‪ 33698823‬وتاريــخ ‪1433/12/22‬ه ـ بينمــا دعــوى املدعــي‬\n‫ضــد املدعــى عليــه واملنتهيــة لــدى احلاكــم الشــرعي بالقــرار رقــم‬\n‫‪ 33263790‬وتاريــخ ‪1433/05/24‬ه ـ محالــة برقــم ‪ 33270741‬وتاريــخ‬\n‫ـدي ممــا يــدل علــى أن‬‫‪1433/04/18‬ه ـ اي قبــل هــذه الدعــوى التــي لـ ّ‬\n‫املدعــي‪ُ ).....(/‬يطالــب بحــق قــد حكــم فيــه لصالــح املدعــى عليــه لــدى‬\n‫حاكــم شــرعي ومــع ذلــك لــم يرتــدع ممــا يــدل أن دعــواه هــذه دعــوى‬\n‫كيديــة‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا تقــدم ذكــره‬\n‫ـدي أن هــذه الدعــوى منتهيــة أساســا بالقــرار املشــار‬‫مفصــا فقــد ثبــت لـ ّ‬\n‫إليــه آنفــا مــن قبــل احلاكــم الشــرعي القاضــي بهــذه احملكمــة الشــيخ‬\n‫ـدي كيديــة‬ ‫ومنتهيــة أيضــا مبجــازاة املدعــي أيضــا للحــق العــام وثبــت لـ ّ‬\n‫هــذه الدعــوى وبنــاء للمــادة الرابعــة مــن نظــام املرافعــات الشــرعية‬\n‫الفقــرة اخلامســة مــن الالئحــة التنفيذيــة للمــادة نفســها فقــد حكمــت‬\n‫بــرد الدعــوى هــذه وحكمــت علــى املدعــي بجلــده أربعــن جلــده دفعــة‬\n‫واحــده أمــام مجمــع احملاكــم الشــرعية باملدينــة املنــورة وأخــذ التعهــد‬\n‫عليــه بعــدم العــودة ملثــل مــا بــدر منــه مســتقبال وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي عــدم القناعــة باحلكــم وأســتعد بتقــدمي الئحــة‬\n‫اعتراضيــة فأفهــم باملراجعــة خــال عشــرة أيــام الســتالم صــورة مــن‬\n‫صــك احلكــم لتقــدمي الئحتــه االعتراضيــة وأفهــم بــأن مــدة االعتــراض‬\n‫ثالثــون يومـ ًا مــن تاريــخ اســتالم صــورة الصــك فــإذا لــم يقــدم اعتراضـ ًا‬\n‫خــال هــذه املــدة ســقط حقــه يف طلــب االســتئناف وأكتســب احلكــم‬\n‫القطعيــة ففهــم ذلــك‪ ،‬فيمــا قــرر املدعــى عليــه القناعــة باحلكــم‪ ،‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف ‪1434/6/26‬ه ـ‬\n\n\n                                                                                     ‫‪306‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪34/1033277‬‬\n      ‫وتاريــخ ‪1434/9/14‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34265082‬وتاريــخ‬\n      ‫‪1434/7/11‬ه الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة املتضمــن دعــوى (‪ ).....‬ســعودي اجلنســية ضــد‪/‬‬\n      ‫(‪ ).....‬مينــي اجلنســية يف التلفــظ عليــه وضربــه‪ ،‬احملكــوم فيــه مبــا دون‬\n      ‫بباطنــه‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا‬\n      ‫املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫آلــه وصحبــه وســلم‪،،،..‬‬\n\n\n\n\n‫‪307‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":302,"source_page_end":307,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2028d28306e986501d67e83edfa14f0f0d2355e726a7021872cdeea5d46661b5","normalized_text_hash":"c873f66b13776733aced651a86a9de8883b650d3fff7b0d257331b9c5b5824cd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p302-34265082"},{"id":"8c8ea964-8587-5e1e-9cb3-1c9738616845","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -انتهاك حرمة منزل بدخوله -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه .","document_number":"34269659","case_number":"33703222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/16","year":"1434","subject":"إيذاء الغير (حق خاص) -انتهاك حرمة منزل بدخوله -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34269659 :‬‬\n                   ‫َر ْق ُم الدعوى‪33703222 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34316989‬تاريخه‪1434/09/10 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬انتهــاك حرمــة منــزل بدخولــه‪ -‬مطالبــة‬\n‫املدعــي باملجــازاة‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬إدانــة املدعــى عليــه ‪.‬‬\n\n\n\n\n                                                      ‫‪ -1‬ال عذر ملقر‪.‬‬\n                   ‫‪ -2‬املواد (‪ )196،195،194‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــام بدخــول بيتــه وغرفــة زوجتــه لغــرض‬\n‫ســيئ وقــد حكــم عليــه يف احلــق العــام بالســجن واجللــد‪ ،‬ولــذا فقــد طلــب‬\n‫تعزيــره حلقــه اخلــاص‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى جملــة‬\n‫وتفصي ـاً‪ -‬املدعــى عليــه أقــر بدخــول منــزل املدعــي ولغرفــة نومــه‬\n‫التــي بهــا زوجتــه وال عــذر ملقــر‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه‬\n‫بدخــول منــزل املدعــي وانتهاكــه حلرمتــه وقــررت تعزيــره للحــق اخلــاص‬\n‫بســجنه ملــدة ســنة وســتة أشــهر وجلــده خمســن جلــدة تكــرر عليــه عشــر‬\n‫مــرات وبحضــور املدعــي باحلــق اخلــاص إن أراد احلضــور‪ -‬عــارض املدعــي‬\n‫واملدعــى عليــه علــى احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى‬\n                                                                        ‫احلكــم‪.‬‬\n\n\n\n                                                                                      ‫‪308‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 33703222‬وتاريــخ ‪1433/12/26‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332238117‬وتاريــخ ‪1433/12/26‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافــق ‪1434/03/14‬ه ـ افتتحــت اجللســة الســاعة ‪08 :30‬‬\n      ‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...‬‬\n      ‫ولــم يحضــر املدعــى عليــه ولــم تردنــا إفــادة بتبليــغ املدعــى عليــه مــن‬\n      ‫عدمــه وعليــه فقــد مت حتديــد موعــد جلســة أخــرى ويف يــوم االثنــن‬\n      ‫املوافق‪1434/03/23‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 :30‬وفيهــا حضــر‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ولــم يحضــر املدعــى‬\n      ‫عليــه ‪ ........‬وقــد وردنــا خطــاب مديــر شــرطة الفيصليــة يفيــد فيــه عــدم‬\n      ‫معرفتهــم عنــوان املذكــور وعليــه فقــد قــررت إرســال املعاملــة إلــى‬\n      ‫شــرطة الفيصليــة ألجــل إحضــار املذكــور رفــق املعاملــة يف أي وقــت‬\n      ‫مــن أوقــات الــدوام الرســمي وختمــت اجللســة ويف يــوم األحــد املوافــق‬\n      ‫‪1434/07/16‬ه ـ افتتحــت اجللســة الســاعة ‪ 10:15‬وفيهــا حضــر املدعــي‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ) ...‬وادعــى علــى احلاضر‬\n      ‫ا يف دعــواه‪ :‬أثنــاء خروجــي‬     ‫معــه ‪ ....‬مبوجــب الســجل املدنــي رقــم قائ ـ ً‬\n      ‫لعملــي يف يــوم اخلميــس ‪1434/09/18‬ه ـ شــاهدت املدعــى عليــه وكان‬\n      ‫يظهــر عليــه مظهــر اخلــوف فلمــا وصلــت إلــى مقــر عملــي اتصلــت علــي‬\n      ‫زوجتــي وأخبرتنــي بــأن يف البيــت حرامــي فخرجــت مــن عملــي واتصلــت‬\n      ‫علــى غرفــة العمليــات وبعدهــا حضــرت الدوريــة وأنــا أتهــم هــذا احلاضــر‬\n\n‫‪309‬‬\n\f‫بقيامــه بدخــول بيتــي وغرفــة زوجتــي لغــرض ســيء وقــد حكــم عليــه‬\n‫يف احلــق العــام بالســجن مــدة خمســة أشــهر وتعزيــره باجللــد وأنــا أطلــب‬\n‫تعزيــره حلقــي اخلــاص هــذه دعــواي‪ .‬وبعــرض مــا جــاء يف الدعــوى علــى‬\n‫املدعــى عليــه قــال‪ :‬أقــر بأنــه يف متــام الســاعة اخلامســة والنصــف صباحـ ًا‬\n‫مــن يــوم اخلميــس املوافــق ‪1432/9/18‬ه ـ قمــت بالدخــول إلــى منــزل‬\n‫املدعــو‪ /‬بشــقق ( ) واجتهــت إلــى غرفــة النــوم وكانــت مقفلــة وفتحتهــا‬\n‫فوجــدت زوجــة املدعــي وأبنــاءه يف الغرفــة وكانــت زوجتــه صاحيــة‬\n‫مــن النــوم وكان جوالهــا بيدهــا وعنــد دخولــي للغرفــة قامــت الزوجــة‬\n‫بالصيــاح بقولهــا (حرامــي) فهربــت وخرجــت مــن نفــس الشــباك الــذي‬\n‫دخلــت معــه واجتهــت إلــى منزلــي بالــدور األول يف نفــس العمــارة هكــذا‬\n‫أقــر‪ .‬وبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫بقيامــه بالدخــول ملنــزل املدعــي ولغرفــة نومــه التــي بهــا زوجتــه‪ ،‬وال‬\n‫عــذر ملقــر‪ ،‬فقــد ثبــت لــدي إدانتــه بدخولــه ملنــزل املدعــي وانتهاكــه‬\n‫حلرمــة منزلــه‪ .‬عليــه فقــد حكمــت علــى املدعــى عليــه يف احلــق اخلــاص‬\n‫باآلتــي‪ :‬ســجنه مــدة ســنة وســتة أشــهر يحتســب منهــا مــدة إيقافــه علــى‬\n‫ذمــة هــذه القضيــة‪ ،‬جلــده خمســن جلــدة تعزيــر ًا تكــرر عليــه عشــر‬\n‫مــرات بــن كل دفعتــن مــدة شــهر وبحضــور املدعــي باحلــق اخلــاص‬\n‫إن أراد احلضــور‪ .‬ومبــا ســلف حكمــت‪ .‬وبعــرض احلكــم علــى املدعــي‬\n‫قــرر‪ :‬عــدم القناعــة بالئحــة اعتراضيــة فأجبتــه لذلــك‪ ،‬وجــرى إعالمــه‬\n‫مبنطــوق املــواد اآلتيــة مــن نظــام اإلجــراءات اجلزائيــة وهــي‪ :‬أوالً‪ :‬املــادة‬\n‫الرابعــة والتســعون بعــد املائــة‪ :‬مــدة االعتــراض بطلــب التمييــز ثالثــون‬\n‫يوم ـ ًا مــن تاريــخ تســلم صــورة احلكــم‪ ،‬وحتــدد احملكمــة بعــد النطــق‬\n‫باحلكــم موعــد ًا أقصــاه عشــرة أيــام لتســلم صــورة احلكــم‪ .‬مــع إثبــات‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫ذلــك يف ضبــط القضيــة وأخــذ توقيــع طالــب التمييــز علــى ذلــك‪ ،‬ويف‬\n      ‫حالــة عــدم حضــوره لتســلم صــورة احلكــم تــودع يف ملــف الدعــوى يف‬\n      ‫التاريــخ نفســه‪ ،‬مــع إثبــات ذلــك يف ضبــط القضيــة بأمــر مــن القاضــي‪.‬‬\n      ‫ويعــد اإليــداع بدايــة مليعــاد الثالثــن يومـ ًا املقــررة لطلــب متييــز احلكــم‪،‬‬\n      ‫وعلــى اجلهــة املســؤولية عــن الســجني إحضــاره لتســلم صــورة احلكــم‬\n      ‫خــال املــدة احملــددة لتســلمها‪ ،‬وكذلــك إحضــاره لتقــدمي اعتراضــه‬\n      ‫يف املــدة احملــددة لتقــدمي االعتــراض‪ .‬ثاني ـاً‪ :‬املــادة اخلامســة والتســعون‬\n      ‫بعــد املائــة‪ :‬إذا لــم يقــدم طالــب التمييــز الئحــة االعتــراض خــال املــدة‬\n      ‫املنصــوص عليهــا يف املــادة الرابعــة والتســعني بعــد املائة‪ ،‬ترفع احملكمة‬\n      ‫احلكــم إلــى محكمــة التمييــز خــال خمســة وأربعــن يوم ـ ًا مــن تاريــخ‬\n      ‫النطــق باحلكــم‪ .‬ثالث ـاً‪ :‬املــادة السادســة والتســعون بعــد املائــة‪ :‬تقــدم‬\n      ‫الالئحــة االعتراضيــة إلــى احملكمــة التــي أصــدرت احلكــم مشــتملة‬\n      ‫علــى بيــان احلكــم املعتــرض عليــه وتاريخــه واألســباب التــي بنــي عليهــا‪،‬‬\n      ‫وطلبــات املعتــرض واألســباب التــي تؤيــد اعتراضــه‪ .‬كمــا قــرر املدعــى‬\n      ‫عليــه اعتراضــه دون الئحــة وختمــت اجللســة بذلــك وكان ختامهــا‬\n      ‫الســاعة ‪ 11:45‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/16‬هــ‪.‬‬\n\n\n\n\n‫‪311‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":308,"source_page_end":311,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cfeb8e782584a9ef90898d2824f49db7f15869ae1671590dbd927890caf2bb2b","normalized_text_hash":"c0a6e813a8a850d11e704a76b5ccbadef8759718ba151eaf668943cf815a5aa4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p308-34269659"},{"id":"0035fdbd-31b2-52e7-bc3d-e3273c9794c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إدانة","document_number":"34240791","case_number":"33706311","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 312 املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/28","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/28 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34240791 :‬‬\n                   ‫َر ْق ُم الدعوى‪33706311 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34333316‬تاريخه‪1434/10/19:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة‬\n‫‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬إدانــة‬\n                                                              ‫املدعــى عليــه‪.‬‬\n\n\n\n‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                             ‫ومالــه وعرضه)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليهمــا قامــا باالعتــداء عليــه بالضــرب ممــا‬\n‫تســبب يف إصابتــه بكدمــات يف الشــفة العليــا وحتــت الذقــن وحــول‬\n‫الرقبــة والكتــف األيســر‪ ،‬ولــذا فقــد طلــب احلكــم عليهمــا بعقوبــة‬\n‫تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه األول مبــا جــاء يف الدعــوى جملــة‬\n‫وتفصيــا كمــا أقــر املدعــى عليــه الثانــي باملشــاركة بقصــد التفريــق‬\n‫بينهمــا‪ -‬املدعــى عليهمــا أقــرا بضــرب املدعــي يف احلكــم الصــادر‬\n‫ضدهمــا للحــق العــام‪ -‬قضــت احملكمــة بإدانــة املدعــى عليهمــا مبــا‬\n‫نســب إليهمــا وقــررت جلــد كل واحــد منهمــا ســتني جلــدة دفعــة واحــدة‬\n‫مــع أخــذ التعهــد عليهمــا بعــدم تكــرار مــا بــدر منهمــا‪ -‬قنــع املدعــى‬\n‫عليهمــا باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف‬\n\n                                                                                     ‫‪312‬‬\n\f                                                             ‫املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف محكمــة محافظــة‬\n      ‫شــرورة العامــة وبنــاء علــى املعاملة احملالة لنــا من فضيلة رئيس محكمة‬\n      ‫محافظــة شــرورة العامــة برقــم ‪ 33706311‬وتاريــخ ‪ 1433/12/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332250743‬وتاريــخ ‪1433/12/27‬ه ـ بشــأن‬\n      ‫دعــوى (‪ ).....‬ســعودي بالبطاقــة رقــم (‪ ).....‬ضــد(‪ ).....‬يف مضاربــة عليــه‬\n      ‫ففــي يــوم االثنــن املوافــق ‪1434/05/20‬ه ـ افتتحــت اجللســة الســاعة ‪15‬‬\n      ‫‪ 11 :‬وفيهــا حضــر املدعــي وحضــر حلضــوره املدعــى عليــه األول (‪).....‬‬\n      ‫ســعودي بالبطاقــة رقــم(‪ ).....‬ولــم يحضــر املدعــى عليــه الثانــي وال مــن‬\n      ‫ميثلــه ولــم يتقــدم بــأي عــذر وقــد وردنــا خطــاب شــرطة شــرورة رقــم‬\n      ‫‪ 2783/102/2‬يف ‪1434/5/8‬ه ـ واملتضمــن تبليــغ املدعــى عليــه الثانــي‬\n      ‫لشــخصه وقــد ادعــى املدعــي قائــا إن املدعــى عليهمــا هــذا احلاضــر‬\n      ‫باجللســة (‪ ).....‬والغائــب عــن اجللســة (‪ ).....‬قامــا باالعتــداء علــي وضربــي‬\n      ‫وتســببا يف إصابتــي بكدمــات يف الشــفة العليــا وحتــت الذقــن وحــول‬\n      ‫الرقبــة والكتــف األيســر وصــدر بذلــك تقريــر طبــي مــن مستشــفى‬\n      ‫شــرورة العــام فأطلــب مجازاتهمــا لقــاء ذلــك هكــذا ادعــى وبعــرض‬\n      ‫دعــواه علــى املدعــى عليــه األول (‪ ).....‬أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫صحيــح فقــد قمــت بضربــه ألنــه كان يتكلــم علــى واحــد مــن أقاربــي‬\n      ‫هكــذا أجــاب ثــم جــرى رفــع اجللســة يف الســاعة الثانيــة عشــرة وذلــك‬\n      ‫إلحضــار املدعــى عليــه الثانــي وحــدد لهــم جلســة أخــرى يــوم األحــد‬\n      ‫املوافــق ‪1434/5/26‬ه الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n‫‪313‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/6/13‬ه ـ‬\n‫الســاعة التاســعة والنصــف فتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫واملدعــى عليــه واملدعــى عليــه الثانــي الســعودي بالبطاقــة رقــم وبعــرض‬\n‫دعــوى املدعــي علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي مــن‬\n‫مشــاركتي فصحيــح غيــر أننــي كنــت أريــد التفريــق بينهمــا وليــس‬\n‫قصــدي الضــرب هكــذا أجــاب ثــم أطلعــت علــى القــرار رقــم ‪/3/45‬ص‬\n‫يف ‪1433/7/13‬ه الصــادر ضــد املدعــى عليهمــا يف احلــق العــام واملتضمن‬\n‫إقرارهمــا مبضاربــة املدعــي وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ومصادقــة املدعــى عليهمــا علــى قيامهمــا بضــرب املدعــي وألن مــا قامــا‬\n‫بــه يعــد فعــا محرمــا ومعاقــب عليــه شــرعا ولقولــه صلــى اهلل عليــه‬\n‫وســلم‪« :‬كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه»‪ .‬فقــد‬\n‫حكمــت علــى املدعــى عليهمــا بجلــد كل واحــد منهمــا ســتني جلــدة‬\n‫دفعــة واحــدة وأخــذ التعهــد عليهمــا بعــدم تكــرار مــا بــدر منهمــا وبذلــك‬\n‫حكمــت وبعرضــه عليهــم قــرر املدعــي عــدم قناعتــه باحلكــم وطلــب‬\n‫رفعهــا حملكمــة االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه وجــرى‬\n‫تســليمه صــورة مــن القــرار لتقــدمي اعتراضــه خــال املــدة املقــررة نظامــا‬\n‫واملدعــى عليهمــا قــررا القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/11/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9:22‬وقــد وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف بعســير برقم ‪ 342205863‬يف ‪1434/11/6‬هـ مشــفوعا بها‬\n‫قــرار الدائــرة اجلزائيــة الثانيــة رقم ‪ 34333316‬وتاريــخ ‪1434/10/19‬هـ‬\n\n\n                                                                                     ‫‪314‬‬\n\f      ‫واملتضمــن املوافقــة علــى احلكــم الصــادر منــا بالقــرار رقــم ‪34240791‬‬\n      ‫وتاريــخ ‪1434/8/28‬ه ـ وحتــى ال يخفــى جــرى إثباتــه وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/11/24‬ه ـ‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":312,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2c87478e9443175fef94a84913bf5ab6969b1a373a3736a18c0e464f48eeefc8","normalized_text_hash":"e35b9ee1a5fd4c915c1e14ed8a8591da50ee999f6ace49c511e18c9271d7b9c4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p312-34240791"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

